window.HADITH={"bukhari-2222":{"id":"bukhari-2222","title":"نزول عيسى ابن مريم حكمًا عدلًا","text":"«والذي نفسي بيده ليوشكن أن ينزل فيكم ابن مريم حكمًا مقسطًا، فيكسر الصليب، ويقتل الخنزير، ويضع الجزية، ويفيض المال حتى لا يقبله أحد».","source":"صحيح البخاري، كتاب البيوع، باب قتل الخنزير؛ وأخرجه مسلم في كتاب الإيمان","number":"2222","grade":"صحيح","url":"https://sunnah.com/bukhari:2222"},"muslim-854":{"id":"muslim-854","title":"خلق آدم يوم الجمعة","text":"«خير يوم طلعت عليه الشمس يوم الجمعة، فيه خُلق آدم، وفيه أُدخل الجنة، وفيه أُخرج منها، ولا تقوم الساعة إلا في يوم الجمعة».","source":"صحيح مسلم، كتاب الجمعة","number":"854","grade":"صحيح","url":"https://sunnah.com/muslim:854a"},"bukhari-4920":{"id":"bukhari-4920","title":"أصنام قوم نوح","text":"عن ابن عباس رضي الله عنهما: «صارت الأوثان التي كانت في قوم نوح في العرب بعدُ… أسماء رجال صالحين من قوم نوح، فلما هلكوا أوحى الشيطان إلى قومهم أن انصبوا إلى مجالسهم التي كانوا يجلسون أنصابًا وسمّوها بأسمائهم، ففعلوا، فلم تُعبد، حتى إذا هلك أولئك وتنسّخ العلم عُبدت».","source":"صحيح البخاري، كتاب التفسير، سورة نوح","number":"4920","grade":"صحيح (موقوف على ابن عباس)","url":"https://sunnah.com/bukhari:4920"},"bukhari-3":{"id":"bukhari-3","title":"بدء الوحي","text":"عن عائشة رضي الله عنها في بدء الوحي: «…حتى جاءه الحق وهو في غار حراء، فجاءه الملك فقال: اقرأ، قال: ما أنا بقارئ…» ثم ذهابه إلى خديجة، وانطلاقها به إلى ورقة بن نوفل الذي قال: «هذا الناموس الذي نزّل الله على موسى».","source":"صحيح البخاري، كتاب بدء الوحي","number":"3","grade":"صحيح","url":"https://sunnah.com/bukhari:3"},"bukhari-3521":{"id":"bukhari-3521","title":"عمرو بن لحي أول من غيّر دين إبراهيم","text":"«رأيت عمرو بن عامر بن لحي الخزاعي يجرّ قُصبه في النار، وكان أول من سيّب السوائب».","source":"صحيح البخاري، كتاب المناقب، باب قصة خزاعة","number":"3521","grade":"صحيح","url":"https://sunnah.com/bukhari:3521"},"bukhari-3401":{"id":"bukhari-3401","title":"قصة موسى والخضر","text":"معنى الحديث: قام موسى خطيبًا في بني إسرائيل فسئل: أي الناس أعلم؟ فقال: أنا، فعتب الله عليه إذ لم يردّ العلم إليه، فأوحى إليه أن عبدًا بمجمع البحرين هو أعلم منك… ثم ساق قصة الحوت والسفينة والغلام والجدار.","source":"صحيح البخاري، كتاب أحاديث الأنبياء (وفي كتاب العلم والتفسير)","number":"3401","grade":"صحيح","url":"https://sunnah.com/bukhari:3401"},"bukhari-3331":{"id":"bukhari-3331","title":"استوصوا بالنساء","text":"«استوصوا بالنساء، فإن المرأة خُلقت من ضلع، وإن أعوج شيء في الضلع أعلاه، فإن ذهبت تقيمه كسرته، وإن تركته لم يزل أعوج، فاستوصوا بالنساء».","source":"صحيح البخاري، كتاب أحاديث الأنبياء","number":"3331","grade":"صحيح","url":"https://sunnah.com/bukhari:3331"},"bukhari-335":{"id":"bukhari-335","title":"بُعثت إلى الناس عامة","text":"«أُعطيت خمسًا لم يعطهن أحد قبلي… وكان النبي يُبعث إلى قومه خاصة، وبُعثت إلى الناس عامة».","source":"صحيح البخاري، كتاب التيمم؛ ومسلم في كتاب المساجد","number":"335","grade":"صحيح","url":"https://sunnah.com/bukhari:335"},"bukhari-2652":{"id":"bukhari-2652","title":"خير الناس قرني","text":"«خير الناس قرني، ثم الذين يلونهم، ثم الذين يلونهم…».","source":"صحيح البخاري، كتاب الشهادات؛ ومسلم في فضائل الصحابة","number":"2652","grade":"صحيح","url":"https://sunnah.com/bukhari:2652"},"bukhari-3461":{"id":"bukhari-3461","title":"بلّغوا عني ولو آية، وحدّثوا عن بني إسرائيل ولا حرج","text":"«بلِّغوا عني ولو آية، وحدِّثوا عن بني إسرائيل ولا حرج، ومن كذب عليَّ متعمدًا فليتبوأ مقعده من النار»","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب ما ذُكر عن بني إسرائيل، من حديث عبد الله بن عمرو رضي الله عنهما","number":"3461","grade":"صحيح","url":"https://sunnah.com/bukhari:3461"},"bukhari-4485":{"id":"bukhari-4485","title":"لا تصدّقوا أهل الكتاب ولا تكذّبوهم","text":"عن أبي هريرة رضي الله عنه قال: كان أهل الكتاب يقرؤون التوراة بالعبرانية ويفسّرونها بالعربية لأهل الإسلام، فقال رسول الله صلى الله عليه وسلم: «لا تصدِّقوا أهل الكتاب ولا تكذِّبوهم، وقولوا: آمنا بالله وما أُنزل إلينا» الآية.","source":"صحيح البخاري، كتاب التفسير، باب «قولوا آمنا بالله وما أنزل إلينا»","number":"4485","grade":"صحيح","url":"https://sunnah.com/bukhari:4485"},"bukhari-7363":{"id":"bukhari-7363","title":"ابن عباس: كيف تسألون أهل الكتاب وكتابكم أحدث الأخبار بالله","text":"معنى الأثر: أنكر ابن عباس رضي الله عنهما على الناس أن يسألوا أهل الكتاب عن شيء، وكتابهم الذي أنزل على نبيهم صلى الله عليه وسلم أحدث الكتب عهدًا بالله، يقرؤونه محضًا لم يُشَب، وقد أخبرهم الله أن أهل الكتاب بدّلوا وغيّروا، ثم قال: أما ينهاكم ما جاءكم من العلم عن مسألتهم؟ ولا والله ما رأينا منهم رجلًا يسألكم عن الذي أُنزل عليكم.","source":"صحيح البخاري، كتاب الاعتصام بالكتاب والسنة، باب قول النبي صلى الله عليه وسلم «لا تسألوا أهل الكتاب عن شيء»","number":"7363","grade":"صحيح (موقوف على ابن عباس)","url":"https://sunnah.com/bukhari:7363"},"bukhari-7361":{"id":"bukhari-7361","title":"معاوية يذكر كعب الأحبار","text":"معنى الأثر: ذكر معاوية رضي الله عنه كعبَ الأحبار في رهط من قريش بالمدينة، فقال: إنه كان من أصدق هؤلاء المحدّثين الذين يحدّثون عن أهل الكتاب، وإن كنا مع ذلك لنبلو عليه الكذب.","source":"صحيح البخاري، كتاب الاعتصام بالكتاب والسنة","number":"7361","grade":"صحيح (موقوف على معاوية)","url":"https://sunnah.com/bukhari:7361"},"muslim-muqaddima-isnad":{"id":"muslim-muqaddima-isnad","title":"ابن سيرين: إن هذا العلم دين","text":"قال محمد بن سيرين: «إن هذا العلم دين، فانظروا عمّن تأخذون دينكم». وقال: «لم يكونوا يسألون عن الإسناد، فلما وقعت الفتنة قالوا: سمُّوا لنا رجالكم، فيُنظر إلى أهل السنة فيؤخذ حديثهم، ويُنظر إلى أهل البدع فلا يؤخذ حديثهم». وقال عبد الله بن المبارك: «الإسناد من الدين، ولولا الإسناد لقال من شاء ما شاء».","source":"مقدمة صحيح مسلم، باب في أن الإسناد من الدين","number":"","grade":"آثار ثابتة عن قائليها","url":""},"muslim-muqaddima-kafa":{"id":"muslim-muqaddima-kafa","title":"كفى بالمرء كذبًا أن يحدّث بكل ما سمع","text":"«كفى بالمرء كذبًا أن يحدِّث بكلِّ ما سمع»","source":"مقدمة صحيح مسلم، باب النهي عن الحديث بكل ما سمع، من حديث أبي هريرة رضي الله عنه","number":"","grade":"صحيح","url":""},"ahmad-umar-tawrat":{"id":"ahmad-umar-tawrat","title":"أمتهوّكون فيها يا ابن الخطاب؟","text":"معنى الحديث: أتى عمر بن الخطاب رضي الله عنه النبيَّ صلى الله عليه وسلم بكتاب أصابه من بعض أهل الكتاب فقرأه عليه، فغضب النبي صلى الله عليه وسلم وقال: «أمتهوِّكون فيها يا ابن الخطاب؟» وأخبر أنه جاءهم بها بيضاء نقية، وقال: «والذي نفسي بيده لو أن موسى كان حيًّا ما وسعه إلا أن يتبعني».","source":"مسند الإمام أحمد من حديث جابر بن عبد الله، ورواه الدارمي وغيره بنحوه","number":"","grade":"في إسناده مجالد بن سعيد وهو ضعيف، وحسّنه بعض المحدثين (كالألباني في إرواء الغليل) بمجموع طرقه وشواهده","url":""},"muslim-2789":{"id":"muslim-2789","title":"حديث التربة: خلق الله التربة يوم السبت","text":"معنى الحديث: روي عن أبي هريرة مرفوعًا أن الله خلق التربة يوم السبت، والجبال يوم الأحد، والشجر يوم الاثنين، والمكروه يوم الثلاثاء، والنور يوم الأربعاء، وبثّ فيها الدواب يوم الخميس، وخلق آدم بعد العصر من يوم الجمعة في آخر الخلق.","source":"صحيح مسلم، كتاب صفة القيامة والجنة والنار","number":"2789","grade":"أخرجه مسلم، وأعلّه البخاري في التاريخ الكبير وغيره، ورجّحوا أنه من كلام كعب الأحبار","url":"https://sunnah.com/muslim:2789"},"bukhari-3326":{"id":"bukhari-3326","title":"خلق الله آدم وطوله ستون ذراعًا","text":"معنى الحديث: خلق الله آدم وطوله ستون ذراعًا، ثم قال له: اذهب فسلّم على أولئك النفر من الملائكة فاستمع ما يحيّونك به، فإنها تحيتك وتحية ذريتك. فقال: «السلام عليكم»، فقالوا: «السلام عليك ورحمة الله»، فزادوه «ورحمة الله»؛ فكل من يدخل الجنة على صورة آدم، فلم يزل الخلق ينقص بعدُ حتى الآن.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب خلق آدم وذريته؛ ورواه مسلم (2841)","number":"3326","grade":"صحيح","url":"https://sunnah.com/bukhari:3326"},"muslim-2611":{"id":"muslim-2611","title":"لما صوّر الله آدم في الجنة","text":"معنى الحديث: لما صوّر الله آدم في الجنة تركه ما شاء الله أن يتركه، فجعل إبليس يُطيف به ينظر ما هو، فلما رآه أجوف عرف أنه خُلق خلقًا لا يتمالك.","source":"صحيح مسلم، كتاب البر والصلة والآداب، من حديث أنس بن مالك رضي الله عنه","number":"2611","grade":"صحيح","url":"https://sunnah.com/muslim:2611"},"muslim-2996":{"id":"muslim-2996","title":"خُلقت الملائكة من نور","text":"«خُلقت الملائكة من نور، وخُلق الجانّ من مارجٍ من نار، وخُلق آدم مما وُصف لكم»","source":"صحيح مسلم، كتاب الزهد والرقائق، من حديث عائشة رضي الله عنها","number":"2996","grade":"صحيح","url":"https://sunnah.com/muslim:2996"},"tirmidhi-2955":{"id":"tirmidhi-2955","title":"خلق الله آدم من قبضة من جميع الأرض","text":"«إن الله خلق آدم من قبضة قبضها من جميع الأرض، فجاء بنو آدم على قدر الأرض، جاء منهم الأحمر والأبيض والأسود وبين ذلك، والسهل والحَزْن، والخبيث والطيب»","source":"جامع الترمذي، أبواب تفسير القرآن، من حديث أبي موسى الأشعري؛ ورواه أبو داود (4693)","number":"2955","grade":"حسن صحيح (قاله الترمذي، وصححه الألباني)","url":"https://sunnah.com/tirmidhi:2955"},"bukhari-3330":{"id":"bukhari-3330","title":"لولا بنو إسرائيل لم يخنز اللحم، ولولا حواء…","text":"معنى الحديث: لولا بنو إسرائيل لم يَخنَز اللحم (أي لم يُنتن)، ولولا حواء لم تخن أنثى زوجها الدهر.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ ورواه مسلم (1470)","number":"3330","grade":"صحيح","url":"https://sunnah.com/bukhari:3330"},"bukhari-3409":{"id":"bukhari-3409","title":"احتجّ آدم وموسى","text":"معنى الحديث: تحاجّ آدم وموسى، فقال موسى: أنت آدم الذي أخرجتك خطيئتك من الجنة؟ فقال آدم: أنت موسى الذي اصطفاك الله برسالاته وبكلامه، ثم تلومني على أمر قُدّر عليّ قبل أن أُخلق؟ قال رسول الله صلى الله عليه وسلم: «فحجّ آدمُ موسى».","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ ورواه مسلم (2652)","number":"3409","grade":"صحيح","url":"https://sunnah.com/bukhari:3409"},"bukhari-4712":{"id":"bukhari-4712","title":"حديث الشفاعة: أنت أبو البشر","text":"معنى موضع الشاهد: يأتي الناس يوم القيامة آدم فيقولون: أنت أبو البشر، خلقك الله بيده، ونفخ فيك من روحه، وأمر الملائكة فسجدوا لك، اشفع لنا إلى ربك؛ فيذكر آدم أن ربه نهاه عن الشجرة فعصاه، ويقول: نفسي نفسي، اذهبوا إلى غيري، اذهبوا إلى نوح.","source":"صحيح البخاري، كتاب التفسير، سورة الإسراء؛ ورواه مسلم (194)","number":"4712","grade":"صحيح","url":"https://sunnah.com/bukhari:4712"},"bukhari-349":{"id":"bukhari-349","title":"آدم في السماء الدنيا ليلة المعراج","text":"معنى موضع الشاهد: لما عُرج بالنبي صلى الله عليه وسلم إلى السماء الدنيا رأى رجلًا عن يمينه أسوِدة وعن يساره أسوِدة، إذا نظر قِبَل يمينه ضحك وإذا نظر قِبَل شماله بكى، فقال: مرحبًا بالنبي الصالح والابن الصالح. فقال جبريل: هذا آدم، وهذه الأسودة نَسَم بنيه؛ فأهل اليمين أهل الجنة، والأسودة التي عن شماله أهل النار.","source":"صحيح البخاري، كتاب الصلاة، من حديث أبي ذر رضي الله عنه؛ ورواه مسلم (163)","number":"349","grade":"صحيح","url":"https://sunnah.com/bukhari:349"},"bukhari-3334":{"id":"bukhari-3334","title":"وأنت في صلب آدم ألّا تشرك بي","text":"معنى الحديث: يقول الله تعالى لأهون أهل النار عذابًا يوم القيامة: لو أن لك ما في الأرض من شيء أكنت تفتدي به؟ فيقول: نعم، فيقول: قد سألتك ما هو أهون من هذا وأنت في صلب آدم: ألّا تشرك بي شيئًا، فأبيت إلا الشرك.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، من حديث أنس بن مالك؛ ورواه مسلم (2805)","number":"3334","grade":"صحيح","url":"https://sunnah.com/bukhari:3334"},"tirmidhi-3076":{"id":"tirmidhi-3076","title":"مسح ظهر آدم وعمر داود","text":"معنى الحديث: لما خلق الله آدم مسح ظهره فسقط من ظهره كل نسمة هو خالقها من ذريته إلى يوم القيامة، وجعل بين عيني كل إنسان منهم وبيصًا من نور، ثم عرضهم على آدم، فأعجبه وبيصُ رجل منهم، فقيل: هذا داود من آخر الأمم من ذريتك، فسأل عن عمره فقيل: ستون سنة، فقال: زِده من عمري أربعين سنة. فلما انقضى عمر آدم وجاءه ملك الموت قال: أولم يبق من عمري أربعون سنة؟ قال: أولم تعطها ابنك داود؟ «فجحد آدم فجحدت ذريته، ونسي آدم فنسيت ذريته، وخطئ آدم فخطئت ذريته».","source":"جامع الترمذي، أبواب تفسير القرآن، تفسير سورة الأعراف، من حديث أبي هريرة؛ ورواه الحاكم وغيره","number":"3076","grade":"حسن صحيح (قاله الترمذي، وصححه الألباني)","url":"https://sunnah.com/tirmidhi:3076"},"tirmidhi-3075":{"id":"tirmidhi-3075","title":"عمر يُسأل عن آية الميثاق","text":"معنى الحديث: سُئل عمر بن الخطاب عن آية الأعراف في أخذ الذرية، فذكر أنه سمع النبي صلى الله عليه وسلم يُسأل عنها، فأخبر أن الله خلق آدم ثم مسح ظهره فاستخرج منه ذرية فقال: خلقت هؤلاء للجنة وبعمل أهل الجنة يعملون، ثم استخرج ذرية فقال: خلقت هؤلاء للنار وبعمل أهل النار يعملون.","source":"جامع الترمذي، أبواب تفسير القرآن؛ وموطأ مالك، وسنن أبي داود (4703)","number":"3075","grade":"في إسناده انقطاع بين مسلم بن يسار وعمر، وصحّح بعض العلماء معناه لشواهده","url":"https://sunnah.com/tirmidhi:3075"},"bukhari-3335":{"id":"bukhari-3335","title":"على ابن آدم الأول كفل من دمها","text":"«لا تُقتل نفسٌ ظلمًا إلا كان على ابن آدم الأول كِفلٌ من دمها، لأنه أول من سنّ القتل»","source":"صحيح البخاري، كتاب أحاديث الأنبياء، من حديث عبد الله بن مسعود؛ ورواه مسلم (1677)","number":"3335","grade":"صحيح","url":"https://sunnah.com/bukhari:3335"},"muslim-2865":{"id":"muslim-2865","title":"خلقت عبادي حنفاء","text":"معنى الحديث القدسي: يقول الله تعالى: إني خلقت عبادي حنفاء كلهم، وإنهم أتتهم الشياطين فاجتالتهم عن دينهم، وحرّمت عليهم ما أحللت لهم، وأمرتهم أن يشركوا بي ما لم أنزل به سلطانًا.","source":"صحيح مسلم، كتاب الجنة وصفة نعيمها وأهلها، من حديث عياض بن حمار المجاشعي","number":"2865","grade":"صحيح","url":"https://sunnah.com/muslim:2865"},"muslim-2814":{"id":"muslim-2814","title":"ما منكم من أحد إلا وقد وُكّل به قرينه من الجن","text":"معنى الحديث: ما منكم من أحد إلا وقد وُكّل به قرينه من الجن، قالوا: وإياك يا رسول الله؟ قال: وإياي، إلا أن الله أعانني عليه فأسلم، فلا يأمرني إلا بخير.","source":"صحيح مسلم، كتاب صفة القيامة والجنة والنار، من حديث عبد الله بن مسعود","number":"2814","grade":"صحيح","url":"https://sunnah.com/muslim:2814"},"tirmidhi-2499":{"id":"tirmidhi-2499","title":"كل ابن آدم خطّاء","text":"«كلُّ ابنِ آدمَ خطّاء، وخيرُ الخطّائين التوّابون»","source":"جامع الترمذي، أبواب صفة القيامة، من حديث أنس بن مالك؛ ورواه ابن ماجه","number":"2499","grade":"حسن (حسّنه الألباني، وقال الترمذي: غريب)","url":"https://sunnah.com/tirmidhi:2499"},"tirmidhi-3077":{"id":"tirmidhi-3077","title":"حديث سمرة في تسمية الولد عبد الحارث","text":"معنى الحديث: روي عن سمرة بن جندب مرفوعًا أن حواء لما حملت طاف بها إبليس، وكان لا يعيش لها ولد، فقال: سمّيه عبد الحارث، فسمّته فعاش، وكان ذلك من وحي الشيطان وأمره.","source":"جامع الترمذي، أبواب تفسير القرآن، تفسير سورة الأعراف؛ ومسند أحمد","number":"3077","grade":"ضعيف (قال الترمذي: حسن غريب، وأعلّه ابن كثير بثلاث علل، وضعّفه الألباني)","url":"https://sunnah.com/tirmidhi:3077"},"muslim-162":{"id":"muslim-162","title":"لقاء إدريس في السماء الرابعة","text":"معنى الحديث: في حديث الإسراء والمعراج الذي رواه أنس بن مالك، أن جبريل عرج بالنبي ﷺ إلى السماء الرابعة فاستفتح، فإذا هو بإدريس فرحّب به ودعا له بخير، ثم قرأ قول الله تعالى: ﴿ورفعناه مكانًا عليًّا﴾.","source":"صحيح مسلم، كتاب الإيمان، باب الإسراء برسول الله ﷺ إلى السماوات","number":"162","grade":"صحيح","url":"https://sunnah.com/muslim:162"},"bukhari-3339":{"id":"bukhari-3339","title":"شهادة الأمة لنوح","text":"معنى الحديث: يجيء نوح وأمته يوم القيامة، فيسأله الله: هل بلّغت؟ فيقول: نعم أي رب. فيسأل أمته: هل بلّغكم؟ فيقولون: ما جاءنا من نبي. فيقول لنوح: من يشهد لك؟ فيقول: محمد ﷺ وأمته، فتشهد هذه الأمة أنه قد بلّغ، وهو معنى قوله تعالى: ﴿وكذلك جعلناكم أمة وسطًا لتكونوا شهداء على الناس﴾.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب قول الله تعالى: ولقد أرسلنا نوحًا إلى قومه","number":"3339","grade":"صحيح","url":"https://sunnah.com/bukhari:3339"},"bukhari-3340":{"id":"bukhari-3340","title":"نوح في حديث الشفاعة","text":"معنى الحديث: يأتي الناس يوم القيامة نوحًا فيقولون له: أنت أول الرسل إلى أهل الأرض، وسمّاك الله عبدًا شكورًا، فاشفع لنا إلى ربك. فيعتذر ويذكر دعوة دعا بها على قومه، ويقول: نفسي نفسي، اذهبوا إلى غيري، حتى ينتهوا إلى محمد ﷺ.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم، كتاب الإيمان (194)","number":"3340","grade":"صحيح","url":"https://sunnah.com/bukhari:3340"},"muslim-194":{"id":"muslim-194","title":"حديث الشفاعة الطويل","text":"معنى الحديث: رواية أبي هريرة لحديث الشفاعة العظمى، وفيها مجيء الناس إلى آدم ثم نوح ثم إبراهيم ثم موسى ثم عيسى ثم محمد ﷺ.","source":"صحيح مسلم، كتاب الإيمان، باب أدنى أهل الجنة منزلة","number":"194","grade":"صحيح","url":"https://sunnah.com/muslim:194"},"ahmad-6583":{"id":"ahmad-6583","title":"وصية نوح لابنه","text":"معنى الحديث: عن عبد الله بن عمرو أن النبي ﷺ أخبر أن نوحًا لما حضرته الوفاة قال لابنه: إني قاصّ عليك الوصية، آمرك باثنتين وأنهاك عن اثنتين: آمرك بلا إله إلا الله، فإن السماوات السبع والأرضين السبع لو وُضعت في كفة ووُضعت لا إله إلا الله في كفة رجحت بهن، وآمرك بسبحان الله وبحمده فإنها صلاة كل شيء وبها يُرزق الخلق، وأنهاك عن الشرك والكبر.","source":"مسند الإمام أحمد (مسند عبد الله بن عمرو)، وأخرجه البخاري في الأدب المفرد (548)","number":"6583","grade":"صحيح الإسناد (صححه الألباني في السلسلة الصحيحة 134، وصحح إسناده شعيب الأرنؤوط)","url":""},"athar-ashara-qurun":{"id":"athar-ashara-qurun","title":"عشرة قرون بين آدم ونوح","text":"معنى الأثر: عن ابن عباس قال: كان بين نوح وآدم عشرة قرون كلهم على شريعة من الحق، فاختلفوا، فبعث الله النبيين مبشرين ومنذرين. وفي معناه حديث مرفوع عن أبي أمامة أن رجلًا سأل النبي ﷺ: أنبيٌّ كان آدم؟ قال: نعم، مُكلَّم. قال: فكم كان بينه وبين نوح؟ قال: عشرة قرون.","source":"تفسير الطبري (البقرة 213) والمستدرك للحاكم عن ابن عباس؛ وحديث أبي أمامة عند ابن حبان والطبراني","number":"","grade":"صحيح (أثر ابن عباس صححه الحاكم ووافقه الذهبي، وصحح الألباني حديث أبي أمامة في السلسلة الصحيحة 2668)","url":""},"ibnhibban-abidharr":{"id":"ibnhibban-abidharr","title":"حديث أبي ذر الطويل في الأنبياء","text":"معنى الحديث: حديث طويل يُروى عن أبي ذر في عدد الأنبياء والرسل والكتب، وفيه أن من الأنبياء أربعة من السريانيين: آدم وشيث وأخنوخ وهو إدريس، وهو أول من خط بالقلم، ونوح؛ وأربعة من العرب: هود وصالح وشعيب ونبيكم.","source":"صحيح ابن حبان، وحلية الأولياء لأبي نعيم، وغيرهما","number":"","grade":"ضعيف جدًّا (فيه إبراهيم بن هشام الغساني، كذّبه أبو حاتم وأبو زرعة)","url":""},"tirmidhi-sam-ham-yafith":{"id":"tirmidhi-sam-ham-yafith","title":"سام أبو العرب","text":"معنى الحديث: يُروى عن سمرة بن جندب مرفوعًا أن سامًا أبو العرب، وحامًا أبو الحبش، ويافث أبو الروم.","source":"سنن الترمذي، كتاب التفسير، سورة الصافات؛ ومسند أحمد","number":"","grade":"ضعيف (من رواية الحسن البصري عن سمرة، وفي سماعه منه خلاف مشهور، وضعفه الألباني)","url":""},"bukhari-1035":{"id":"bukhari-1035","title":"نُصرت بالصبا وأُهلكت عاد بالدبور","text":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال: «نُصرت بالصَّبا، وأُهلكت عاد بالدَّبور».","source":"صحيح البخاري، كتاب الاستسقاء؛ وصحيح مسلم، كتاب صلاة الاستسقاء (900)","number":"1035","grade":"صحيح","url":"https://sunnah.com/bukhari:1035"},"bukhari-4828":{"id":"bukhari-4828","title":"خوف النبي ﷺ من الغيم","text":"معنى الحديث: قالت عائشة رضي الله عنها: كان النبي ﷺ إذا رأى غيمًا أو ريحًا عُرف ذلك في وجهه، فقلت: يا رسول الله، الناس إذا رأوا الغيم فرحوا رجاء أن يكون فيه المطر، وأراك إذا رأيته عُرفت في وجهك الكراهية! فقال: يا عائشة، ما يؤمنني أن يكون فيه عذاب؟ قد عُذّب قوم بالريح، وقد رأى قوم العذاب فقالوا: هذا عارض ممطرنا.","source":"صحيح البخاري، كتاب التفسير، سورة الأحقاف (4828 أو 4829 بحسب الطبعة)؛ وصحيح مسلم (899)","number":"4828","grade":"صحيح","url":"https://sunnah.com/bukhari:4828"},"tirmidhi-wafid-ad":{"id":"tirmidhi-wafid-ad","title":"وافد عاد","text":"معنى الحديث: عن الحارث بن حسان البكري أنه قدم المدينة في وفد، فذكر عند النبي ﷺ «وافد عاد»، فقال: أعوذ بالله أن أكون مثل وافد عاد. فسأله النبي ﷺ عنه، فحكى أن عادًا لما قحطوا بعثوا وافدهم إلى مكة يستسقي لهم، فنزل على معاوية بن بكر فأقام عنده شهرًا يسقيه الخمر وتغنيه جاريتان، ثم خرج إلى جبال مهرة فدعا، فمرت به سحابات فاختار السوداء، فنودي: خذها رمادًا رمددًا لا تُبقي من عاد أحدًا. قال: فما بلغني أنه أُرسل عليهم من الريح إلا قدر ما يجري في خاتمي هذا حتى هلكوا.","source":"مسند أحمد (حديث الحارث بن حسان)؛ سنن الترمذي، كتاب التفسير، سورة الذاريات؛ سنن ابن ماجه مختصرًا","number":"","grade":"حسن عند جماعة من أهل العلم (أورده ابن كثير محتجًا به)، وفي إسناده عاصم بن بهدلة وفيه كلام يسير","url":""},"bukhari-4942":{"id":"bukhari-4942","title":"انبعث لها رجل عزيز عارم","text":"معنى الحديث: عن عبد الله بن زمعة أنه سمع النبي ﷺ يخطب وذكر الناقة والذي عقرها، فقال: «إذ انبعث أشقاها»: انبعث لها رجل عزيز عارم منيع في رهطه مثل أبي زمعة.","source":"صحيح البخاري، كتاب التفسير، سورة الشمس؛ وأخرجه مسلم بنحوه","number":"4942","grade":"صحيح","url":"https://sunnah.com/bukhari:4942"},"bukhari-3380":{"id":"bukhari-3380","title":"لا تدخلوا مساكن الذين ظلموا","text":"معنى الحديث: عن ابن عمر رضي الله عنهما أن النبي ﷺ لما مرّ بالحِجر قال: «لا تدخلوا مساكن الذين ظلموا أنفسهم إلا أن تكونوا باكين، أن يصيبكم ما أصابهم»، ثم تقنّع بردائه وهو على الرحل.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب قول الله: وإلى ثمود أخاهم صالحًا؛ وصحيح مسلم، كتاب الزهد (2980)","number":"3380","grade":"صحيح","url":"https://sunnah.com/bukhari:3380"},"bukhari-3379":{"id":"bukhari-3379","title":"آبار الحِجر وبئر الناقة","text":"معنى الحديث: عن ابن عمر أن الناس نزلوا مع رسول الله ﷺ أرض ثمود الحِجر، فاستقوا من بئرها واعتجنوا به، فأمرهم رسول الله ﷺ أن يهريقوا ما استقوا من بئرها، وأن يعلفوا الإبل العجين، وأمرهم أن يستقوا من البئر التي كانت تردها الناقة.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم، كتاب الزهد (2981)","number":"3379","grade":"صحيح","url":"https://sunnah.com/bukhari:3379"},"abudawud-3088":{"id":"abudawud-3088","title":"قبر أبي رغال","text":"معنى الحديث: يُروى أن النبي ﷺ لما خرج إلى الطائف مرّ بقبر فقال: هذا قبر أبي رغال، وكان من ثمود، وكان بهذا الحرم يُدفع عنه، فلما خرج أصابته النقمة التي أصابت قومه بهذا المكان فدُفن فيه، وآية ذلك أنه دُفن معه غصن من ذهب إن أنتم نبشتم عنه أصبتموه معه، فابتدره الناس فاستخرجوا الغصن.","source":"سنن أبي داود، كتاب الخراج والإمارة","number":"3088","grade":"مختلف فيه: ضعّفه الألباني وشعيب الأرنؤوط (لجهالة بجير بن أبي بجير)، وحسّنه بعض المتقدمين","url":"https://sunnah.com/abudawud:3088"},"ahmad-jabir-ayat":{"id":"ahmad-jabir-ayat","title":"لا تسألوا الآيات","text":"معنى الحديث: عن جابر بن عبد الله أن النبي ﷺ لما مرّ بالحِجر قال: لا تسألوا الآيات، فقد سألها قوم صالح، فكانت الناقة ترد من هذا الفج وتصدر من هذا الفج، فعتوا عن أمر ربهم فعقروها… فأخذتهم صيحة أهمد الله من تحت أديم السماء منهم إلا رجلًا واحدًا كان في حرم الله، قيل: من هو؟ قال: أبو رغال، فلما خرج من الحرم أصابه ما أصاب قومه.","source":"مسند أحمد (مسند جابر)؛ المستدرك للحاكم","number":"","grade":"صححه الحاكم على شرط مسلم ووافقه الذهبي، وقوّاه ابن كثير","url":""},"ahmad-ali-ashqa":{"id":"ahmad-ali-ashqa","title":"أشقى الأولين وأشقى الآخرين","text":"معنى الحديث: يُروى أن النبي ﷺ قال لعلي رضي الله عنه: ألا أحدثكما بأشقى الناس رجلين؟ أُحيمر ثمود الذي عقر الناقة، والذي يضربك يا علي على هذه — يعني قرنه — حتى تبتل منه هذه — يعني لحيته.","source":"مسند أحمد (حديث عمار بن ياسر)؛ والنسائي في الخصائص؛ والحاكم","number":"","grade":"حسّنه بعض المحدثين بمجموع طرقه، وفي أسانيده مقال","url":""},"ibnhibban-abidharr-ch04":{"id":"ibnhibban-abidharr-ch04","title":"أربعة من العرب","text":"معنى الحديث: في حديث أبي ذر الطويل في عدد الأنبياء: «وأربعة من العرب: هود وصالح وشعيب ونبيك يا أبا ذر».","source":"صحيح ابن حبان؛ حلية الأولياء لأبي نعيم","number":"","grade":"ضعيف جدًّا (فيه إبراهيم بن هشام الغساني)","url":""},"bukhari-3358":{"id":"bukhari-3358","title":"لم يكذب إبراهيم إلا ثلاث كذبات","text":"معنى الحديث: أخبر النبي صلى الله عليه وسلم أن إبراهيم لم يقل ما ظاهره خلاف الواقع إلا ثلاث مرات، ثنتان منهن في ذات الله: قوله «إني سقيم»، وقوله «بل فعله كبيرهم هذا»، والثالثة قوله عن سارة للجبار: «هي أختي»، ثم ذكر قصة سارة مع الجبار وكيف كفّ الله يده عنها، وأخدمها هاجر.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب قول الله تعالى: واتخذ الله إبراهيم خليلًا؛ وأخرجه مسلم (2371)","number":"3358","grade":"صحيح","url":"https://sunnah.com/bukhari:3358"},"bukhari-3364":{"id":"bukhari-3364","title":"حديث ابن عباس الطويل: هاجر وإسماعيل وزمزم وبناء البيت","text":"معنى الحديث: جاء إبراهيم بهاجر وابنها إسماعيل وهي ترضعه فوضعهما عند البيت عند دوحة فوق زمزم، وليس بمكة يومئذ أحد ولا ماء، فقالت: آلله أمرك بهذا؟ قال: نعم، قالت: إذن لا يضيعنا. ثم سعيها بين الصفا والمروة سبعًا، ونبع زمزم، ونزول جرهم، وزواج إسماعيل، وزيارات إبراهيم، وبناء البيت.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب يزفون: النسلان في المشي","number":"3364","grade":"صحيح","url":"https://sunnah.com/bukhari:3364"},"bukhari-3356":{"id":"bukhari-3356","title":"اختتن إبراهيم وهو ابن ثمانين سنة","text":"اختتن إبراهيم عليه السلام وهو ابن ثمانين سنة بالقدوم.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وأخرجه مسلم (2370)","number":"3356","grade":"صحيح","url":"https://sunnah.com/bukhari:3356"},"bukhari-3349":{"id":"bukhari-3349","title":"أول من يكسى يوم القيامة إبراهيم","text":"معنى الحديث: يُحشر الناس يوم القيامة حفاة عراة غرلًا، كما بدأنا أول خلق نعيده، وأول من يكسى يوم القيامة إبراهيم.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وأخرجه مسلم (2860)","number":"3349","grade":"صحيح","url":"https://sunnah.com/bukhari:3349"},"bukhari-3350":{"id":"bukhari-3350","title":"يلقى إبراهيم أباه آزر يوم القيامة","text":"معنى الحديث: يلقى إبراهيم أباه آزر يوم القيامة وعلى وجهه قترة وغبرة، فيذكّره بنصحه، ويسأل ربه ألا يخزيه يوم يبعثون، فيقول الله: إني حرمت الجنة على الكافرين، ثم يُمسخ آزر في صورة ذيخ (ذكر الضباع) متلطخ فيؤخذ بقوائمه فيلقى في النار.","source":"صحيح البخاري، كتاب أحاديث الأنبياء","number":"3350","grade":"صحيح","url":"https://sunnah.com/bukhari:3350"},"bukhari-3359":{"id":"bukhari-3359","title":"الوزغ كان ينفخ على إبراهيم","text":"معنى الحديث: أمر النبي صلى الله عليه وسلم بقتل الوزغ، وقال: كان ينفخ على إبراهيم.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، عن أم شريك رضي الله عنها","number":"3359","grade":"صحيح","url":"https://sunnah.com/bukhari:3359"},"bukhari-4563":{"id":"bukhari-4563","title":"حسبنا الله ونعم الوكيل","text":"معنى الأثر: عن ابن عباس قال: «حسبنا الله ونعم الوكيل» قالها إبراهيم حين ألقي في النار، وقالها محمد صلى الله عليه وسلم حين قالوا له: إن الناس قد جمعوا لكم فاخشوهم.","source":"صحيح البخاري، كتاب التفسير، سورة آل عمران","number":"4563","grade":"صحيح","url":"https://sunnah.com/bukhari:4563"},"bukhari-3372":{"id":"bukhari-3372","title":"نحن أحق بالشك من إبراهيم","text":"معنى الحديث: نحن أحق بالشك من إبراهيم إذ قال: رب أرني كيف تحيي الموتى، ويرحم الله لوطًا لقد كان يأوي إلى ركن شديد، ولو لبثت في السجن طول ما لبث يوسف لأجبت الداعي.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وأخرجه مسلم (151)","number":"3372","grade":"صحيح","url":"https://sunnah.com/bukhari:3372"},"bukhari-3366":{"id":"bukhari-3366","title":"أول مسجد وضع في الأرض","text":"معنى الحديث: سأل أبو ذر النبي صلى الله عليه وسلم: أي مسجد وضع في الأرض أول؟ قال: المسجد الحرام، قال: ثم أي؟ قال: المسجد الأقصى، قال: كم كان بينهما؟ قال: أربعون سنة.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وأخرجه مسلم","number":"3366","grade":"صحيح","url":"https://sunnah.com/bukhari:3366"},"bukhari-3382":{"id":"bukhari-3382","title":"الكريم ابن الكريم","text":"الكريم ابن الكريم ابن الكريم ابن الكريم: يوسف بن يعقوب بن إسحاق بن إبراهيم عليهم السلام.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، عن عبد الله بن عمر","number":"3382","grade":"صحيح","url":"https://sunnah.com/bukhari:3382"},"bukhari-3353":{"id":"bukhari-3353","title":"من أكرم الناس؟","text":"معنى الحديث: سئل النبي صلى الله عليه وسلم: من أكرم الناس؟ قال: أتقاهم، قالوا: ليس عن هذا نسألك، قال: فيوسف نبي الله ابن نبي الله ابن نبي الله ابن خليل الله، قالوا: ليس عن هذا نسألك، قال: فعن معادن العرب تسألوني؟ خيارهم في الجاهلية خيارهم في الإسلام إذا فقهوا.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، عن أبي هريرة؛ وأخرجه مسلم","number":"3353","grade":"صحيح","url":"https://sunnah.com/bukhari:3353"},"bukhari-2899":{"id":"bukhari-2899","title":"ارموا بني إسماعيل","text":"معنى الحديث: مرّ النبي صلى الله عليه وسلم على نفر من أسلم يتناضلون فقال: ارموا بني إسماعيل فإن أباكم كان راميًا.","source":"صحيح البخاري، كتاب الجهاد والسير","number":"2899","grade":"صحيح","url":"https://sunnah.com/bukhari:2899"},"bukhari-279":{"id":"bukhari-279","title":"أيوب وجراد الذهب","text":"بَيْنَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا فَخَرَّ عَلَيْهِ جَرَادٌ مِنْ ذَهَبٍ، فَجَعَلَ أَيُّوبُ يَحْتَثِي فِي ثَوْبِهِ، فَنَادَاهُ رَبُّهُ: يَا أَيُّوبُ، أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى؟ قَالَ: بَلَى وَعِزَّتِكَ، وَلَكِنْ لَا غِنَى بِي عَنْ بَرَكَتِكَ","source":"صحيح البخاري، كتاب الغسل، باب من اغتسل عريانًا وحده في الخلوة؛ وأعاده في كتاب أحاديث الأنبياء (3391)","number":"279","grade":"صحيح","url":"https://sunnah.com/bukhari:279"},"ibnhibban-ayyub":{"id":"ibnhibban-ayyub","title":"بلاء أيوب ثماني عشرة سنة","text":"معنى الحديث: أن أيوب لبث به بلاؤه ثماني عشرة سنة، فرفضه القريب والبعيد إلا رجلين من إخوانه، فقال أحدهما للآخر: لقد أذنب أيوب ذنبًا عظيمًا وإلا لكشف الله عنه، فلما بلغ ذلك أيوب ذكر ورعه في ذكر الله، ثم أوحي إليه: اركض برجلك، فشُفي.","source":"صحيح ابن حبان، ومسند أبي يعلى، والمستدرك للحاكم، من حديث أنس بن مالك","number":"","grade":"صححه ابن حبان والحاكم والألباني (السلسلة الصحيحة)، وتكلم فيه بعضهم","url":""},"abudawud-sick-man":{"id":"abudawud-sick-man","title":"إقامة الحد على المريض بعثكال","text":"معنى الحديث: أن رجلًا مريضًا ضعيفًا أصاب حدًّا، فأمر النبي ﷺ أن يؤخذ عثكال فيه مائة شمراخ فيُضرب به ضربة واحدة، رفقًا به.","source":"سنن أبي داود، كتاب الحدود؛ وابن ماجه","number":"","grade":"صححه جماعة من أهل العلم، وفي إسناده اختلاف","url":""},"tirmidhi-3505":{"id":"tirmidhi-3505","title":"دعوة ذي النون","text":"دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ، فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللَّهُ لَهُ","source":"سنن الترمذي، كتاب الدعوات، من حديث سعد بن أبي وقاص","number":"3505","grade":"صحيح (صححه الحاكم والألباني، وحسنه ابن حجر)","url":"https://sunnah.com/tirmidhi:3505"},"bukhari-3395":{"id":"bukhari-3395","title":"لا ينبغي لعبد أن يقول أنا خير من يونس","text":"لَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ: أَنَا خَيْرٌ مِنْ يُونُسَ بْنِ مَتَّى، وَنَسَبَهُ إِلَى أَبِيهِ","source":"صحيح البخاري، كتاب أحاديث الأنبياء، من حديث ابن عباس؛ ورواه مسلم في كتاب الفضائل","number":"3395","grade":"صحيح","url":"https://sunnah.com/bukhari:3395"},"muslim-yunus-talbiya":{"id":"muslim-yunus-talbiya","title":"كأني أنظر إلى يونس يلبي","text":"معنى الحديث: أن النبي ﷺ مر بثنية في طريقه فقال: كأني أنظر إلى يونس بن متى على ناقة حمراء جعدة، عليه جبة من صوف، خطام ناقته من ليف، وهو يلبي.","source":"صحيح مسلم، كتاب الإيمان، من حديث ابن عباس","number":"","grade":"صحيح","url":""},"tirmidhi-2496":{"id":"tirmidhi-2496","title":"الكفل العاصي التائب","text":"معنى الحديث: أن الكفل كان رجلًا من بني إسرائيل لا يتورع من ذنب، فراود امرأة محتاجة بمال، فلما ارتعدت وبكت خوفًا من الله تركها وترك لها المال، وحلف ألا يعصي الله أبدًا، فمات من ليلته فأصبح مكتوبًا على بابه: إن الله قد غفر للكفل.","source":"سنن الترمذي، أبواب صفة القيامة والرقائق والورع، من حديث ابن عمر؛ ومسند أحمد","number":"2496","grade":"حسّنه الترمذي، واختُلف في رفعه ووقفه، وضعّفه جماعة","url":"https://sunnah.com/tirmidhi:2496"},"bukhari-3404":{"id":"bukhari-3404","title":"إن موسى كان رجلًا حييًّا","text":"«إن موسى كان رجلًا حييًّا ستيرًا لا يُرى من جلده شيء استحياءً منه» — ثم ذكر أن بني إسرائيل آذوه فقالوا ما يستتر هذا التستر إلا من عيب بجلده، فوضع ثيابه على حجر واغتسل، فعدا الحجر بثوبه، فرآه الملأ من بني إسرائيل أحسن ما خلق الله، فبرأه الله مما قالوا، ونزل في ذلك قوله تعالى في سورة الأحزاب: 69.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وأخرجه مسلم (339) باختلاف يسير","number":"3404","grade":"صحيح","url":"https://sunnah.com/bukhari:3404"},"bukhari-3407":{"id":"bukhari-3407","title":"موسى وملك الموت","text":"معنى الحديث: أُرسل ملك الموت إلى موسى فلما جاءه صكه، فرجع إلى ربه فقال: أرسلتني إلى عبد لا يريد الموت، فرد الله عليه عينه وقال: ارجع فقل له يضع يده على متن ثور فله بكل ما غطت يده بكل شعرة سنة، قال: أي رب ثم ماذا؟ قال: ثم الموت، قال: فالآن، فسأل الله أن يدنيه من الأرض المقدسة رمية بحجر. قال رسول الله ﷺ: «فلو كنت ثَمّ لأريتكم قبره إلى جانب الطريق عند الكثيب الأحمر».","source":"صحيح البخاري، كتاب أحاديث الأنبياء (وفي كتاب الجنائز)؛ ومسلم (2372)","number":"3407","grade":"صحيح","url":"https://sunnah.com/bukhari:3407"},"muslim-2375":{"id":"muslim-2375","title":"موسى يصلي في قبره","text":"«مررت على موسى ليلة أُسري بي عند الكثيب الأحمر وهو قائم يصلي في قبره».","source":"صحيح مسلم، كتاب الفضائل، باب من فضائل موسى عليه السلام","number":"2375","grade":"صحيح","url":"https://sunnah.com/muslim:2375"},"bukhari-3887":{"id":"bukhari-3887","title":"حديث المعراج ومراجعة موسى في الصلاة","text":"معنى الحديث: لما فُرضت على النبي ﷺ خمسون صلاة ليلة المعراج مرّ على موسى، فقال له: إن أمتك لا تستطيع خمسين صلاة، وإني قد جربت الناس قبلك وعالجت بني إسرائيل أشد المعالجة، فارجع إلى ربك فاسأله التخفيف لأمتك، فما زال يرجع حتى صارت خمسًا، فقال ﷺ: سألت ربي حتى استحييت ولكني أرضى وأسلم.","source":"صحيح البخاري، كتاب مناقب الأنصار، باب المعراج، من حديث مالك بن صعصعة؛ وأصل القصة في مسلم من حديث أنس","number":"3887","grade":"صحيح","url":"https://sunnah.com/bukhari:3887"},"bukhari-2004":{"id":"bukhari-2004","title":"صيام عاشوراء","text":"معنى الحديث: قدم النبي ﷺ المدينة فرأى اليهود تصوم يوم عاشوراء، فسأل عن ذلك فقالوا: هذا يوم صالح، هذا يوم نجّى الله بني إسرائيل من عدوهم فصامه موسى، فقال ﷺ: فأنا أحق بموسى منكم، فصامه وأمر بصيامه.","source":"صحيح البخاري، كتاب الصوم، باب صيام يوم عاشوراء، من حديث ابن عباس","number":"2004","grade":"صحيح","url":"https://sunnah.com/bukhari:2004"},"muslim-1130":{"id":"muslim-1130","title":"عاشوراء يوم أنجى الله فيه موسى","text":"معنى الحديث: قال اليهود عن يوم عاشوراء: هذا يوم عظيم أنجى الله فيه موسى وقومه وأغرق فرعون وقومه، فصامه موسى شكرًا فنحن نصومه، فقال ﷺ: فنحن أحق وأولى بموسى منكم، فصامه وأمر بصيامه.","source":"صحيح مسلم، كتاب الصيام، من حديث ابن عباس","number":"1130","grade":"صحيح","url":"https://sunnah.com/muslim:1130"},"bukhari-3405":{"id":"bukhari-3405","title":"قد أوذي موسى بأكثر من هذا فصبر","text":"معنى الحديث: قسم النبي ﷺ قسمًا فقال رجل: إن هذه لقسمة ما أريد بها وجه الله، فلما بلغه ذلك غضب حتى رُئي الغضب في وجهه، ثم قال: «يرحم الله موسى، قد أوذي بأكثر من هذا فصبر».","source":"صحيح البخاري، كتاب أحاديث الأنبياء، من حديث عبد الله بن مسعود؛ ومسلم (1062)","number":"3405","grade":"صحيح","url":"https://sunnah.com/bukhari:3405"},"bukhari-3706":{"id":"bukhari-3706","title":"بمنزلة هارون من موسى","text":"معنى الحديث: قال النبي ﷺ لعلي بن أبي طالب حين خلّفه على أهله في غزوة تبوك: أما ترضى أن تكون مني بمنزلة هارون من موسى؟ وفي رواية مسلم: غير أنه لا نبي بعدي.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي ﷺ، باب مناقب علي، من حديث سعد بن أبي وقاص؛ ومسلم (2404)","number":"3706","grade":"صحيح","url":"https://sunnah.com/bukhari:3706"},"bukhari-2411":{"id":"bukhari-2411","title":"لا تخيروني على موسى","text":"معنى الحديث: استبّ رجل من المسلمين ورجل من اليهود، فقال المسلم: والذي اصطفى محمدًا على العالمين، وقال اليهودي: والذي اصطفى موسى على العالمين، فلطمه المسلم، فشكا اليهودي إلى النبي ﷺ فقال: لا تخيروني على موسى، فإن الناس يصعقون يوم القيامة فأكون أول من يفيق فإذا موسى باطش بجانب العرش، فلا أدري أكان فيمن صعق فأفاق قبلي أو كان ممن استثنى الله.","source":"صحيح البخاري، كتاب الخصومات، من حديث أبي هريرة؛ ومسلم (2373)","number":"2411","grade":"صحيح","url":"https://sunnah.com/bukhari:2411"},"muslim-2652":{"id":"muslim-2652","title":"احتجاج آدم وموسى","text":"معنى الحديث: احتج آدم وموسى عند ربهما، فقال موسى: أنت آدم الذي خلقك الله بيده ونفخ فيك من روحه ثم أهبطت الناس بخطيئتك إلى الأرض، فقال آدم: أنت موسى الذي اصطفاك الله برسالته وكلامه، أفتلومني على أمر قدّره الله عليّ قبل أن يخلقني؟ قال ﷺ: فحجّ آدمُ موسى. والحديث في البخاري أيضًا.","source":"صحيح مسلم، كتاب القدر، من حديث أبي هريرة؛ وأخرجه البخاري في كتاب أحاديث الأنبياء وكتاب القدر","number":"2652","grade":"صحيح","url":"https://sunnah.com/muslim:2652"},"bukhari-3124":{"id":"bukhari-3124","title":"النبي الذي حُبست له الشمس","text":"معنى الحديث: غزا نبي من الأنبياء فاشترط ألا يتبعه من عقد على امرأة ولم يدخل بها، ولا من بنى بيوتًا ولم يرفع سقوفها، ولا من اشترى غنمًا أو خَلِفات ينتظر ولادها. فدنا من القرية عند صلاة العصر أو قريبًا منها، فقال للشمس: «إنك مأمورة وأنا مأمور، اللهم احبسها علينا»، فحُبست حتى فتح الله عليه. ثم جمع الغنائم فلم تأكلها النار، فعرف أن فيهم غلولًا، فلزقت يد رجل بيده، فجاؤوا برأسٍ مثل رأس بقرة من ذهب فوضعوه فأكلتها النار، ثم أحل الله لنا الغنائم لما رأى ضعفنا وعجزنا.","source":"صحيح البخاري، كتاب فرض الخمس؛ وصحيح مسلم، كتاب الجهاد والسير (1747)","number":"3124","grade":"صحيح","url":"https://sunnah.com/bukhari:3124"},"bukhari-3403":{"id":"bukhari-3403","title":"ادخلوا الباب سجدًا وقولوا حطة","text":"معنى الحديث: قيل لبني إسرائيل ادخلوا الباب سجدًا وقولوا حطة، فبدّلوا فدخلوا يزحفون على أستاههم، وقالوا: حبة في شعرة.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، وأخرجه مسلم","number":"3403","grade":"صحيح","url":"https://sunnah.com/bukhari:3403"},"bukhari-3957":{"id":"bukhari-3957","title":"عدة أهل بدر على عدة أصحاب طالوت","text":"معنى الحديث: عن البراء بن عازب قال: كنا نتحدث أن عدة أصحاب بدر على عدة أصحاب طالوت الذين جاوزوا معه النهر، ولم يجاوز معه إلا مؤمن، بضعة عشر وثلاثمئة.","source":"صحيح البخاري، كتاب المغازي (تختلف الأرقام بين الطبعات: 3957–3959)","number":"3957","grade":"صحيح","url":"https://sunnah.com/bukhari:3957"},"bukhari-5048":{"id":"bukhari-5048","title":"مزمار من مزامير آل داود","text":"قال النبي صلى الله عليه وسلم لأبي موسى الأشعري: «يا أبا موسى، لقد أوتيت مزمارًا من مزامير آل داود».","source":"صحيح البخاري، كتاب فضائل القرآن؛ وصحيح مسلم (793)","number":"5048","grade":"صحيح","url":"https://sunnah.com/bukhari:5048"},"bukhari-3417":{"id":"bukhari-3417","title":"خُفف على داود القرآن","text":"معنى الحديث: خُفف على داود عليه السلام القرآن (أي قراءة الزبور)، فكان يأمر بدوابّه فتُسرج، فيقرأ قبل أن تُسرج دوابه، ولا يأكل إلا من عمل يده.","source":"صحيح البخاري، كتاب أحاديث الأنبياء","number":"3417","grade":"صحيح","url":"https://sunnah.com/bukhari:3417"},"bukhari-2073":{"id":"bukhari-2073","title":"داود يأكل من عمل يده","text":"«أن داود عليه السلام كان لا يأكل إلا من عمل يده».","source":"صحيح البخاري، كتاب البيوع","number":"2073","grade":"صحيح","url":"https://sunnah.com/bukhari:2073"},"bukhari-1131":{"id":"bukhari-1131","title":"أحب الصيام وأحب الصلاة","text":"«أحب الصلاة إلى الله صلاة داود عليه السلام، وأحب الصيام إلى الله صيام داود، وكان ينام نصف الليل ويقوم ثلثه وينام سدسه، ويصوم يومًا ويفطر يومًا».","source":"صحيح البخاري، كتاب التهجد؛ وصحيح مسلم (1159)","number":"1131","grade":"صحيح","url":"https://sunnah.com/bukhari:1131"},"bukhari-3427":{"id":"bukhari-3427","title":"قضاء سليمان بين المرأتين","text":"معنى الحديث: كانت امرأتان معهما ابناهما، فجاء الذئب فذهب بابن إحداهما، فتنازعتا الباقي، فتحاكمتا إلى داود فقضى به للكبرى، فخرجتا على سليمان فأخبرتاه، فقال: ائتوني بالسكين أشقّه بينهما، فقالت الصغرى: لا تفعل يرحمك الله، هو ابنها، فقضى به للصغرى.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم، كتاب الأقضية (1720)","number":"3427","grade":"صحيح","url":"https://sunnah.com/bukhari:3427"},"bukhari-461":{"id":"bukhari-461","title":"العفريت الذي تفلّت على النبي ودعوة سليمان","text":"معنى الحديث: أن عفريتًا من الجن تفلّت على النبي صلى الله عليه وسلم ليقطع عليه صلاته، فأمكنه الله منه، فأراد أن يربطه إلى سارية من سواري المسجد، ثم ذكر دعوة أخيه سليمان: رب هب لي ملكًا لا ينبغي لأحد من بعدي، فردّه خاسئًا.","source":"صحيح البخاري، كتاب الصلاة؛ وصحيح مسلم (541)","number":"461","grade":"صحيح","url":"https://sunnah.com/bukhari:461"},"bukhari-3019":{"id":"bukhari-3019","title":"النبي الذي قرصته نملة","text":"معنى الحديث: قرصت نملةٌ نبيًّا من الأنبياء فأمر بقرية النمل فأُحرقت، فأوحى الله إليه: أن قرصتك نملة أحرقت أمة من الأمم تسبّح؟","source":"صحيح البخاري، كتاب الجهاد والسير؛ وصحيح مسلم، كتاب السلام","number":"3019","grade":"صحيح","url":"https://sunnah.com/bukhari:3019"},"bukhari-3424":{"id":"bukhari-3424","title":"لأطوفن الليلة","text":"معنى الحديث: قال سليمان بن داود: لأطوفن الليلة على نسائه (في الروايات: ستين، أو سبعين، أو تسعين، أو تسع وتسعين، أو مئة) تلد كل امرأة منهن فارسًا يجاهد في سبيل الله، فقال له صاحبه (أو الملك): قل إن شاء الله، فلم يقل، فلم تحمل منهن إلا امرأة واحدة جاءت بشق رجل، قال النبي صلى الله عليه وسلم: لو قال إن شاء الله لم يحنث، وكان أرجى لحاجته، ولجاهدوا في سبيل الله فرسانًا أجمعون.","source":"صحيح البخاري، كتاب أحاديث الأنبياء وكتاب الأيمان والنذور؛ وصحيح مسلم، كتاب الأيمان (1654)","number":"3424","grade":"صحيح","url":"https://sunnah.com/bukhari:3424"},"nasai-693":{"id":"nasai-693","title":"سؤالات سليمان الثلاث عند بناء بيت المقدس","text":"معنى الحديث: أن سليمان بن داود لما بنى بيت المقدس سأل الله ثلاثًا: حكمًا يصادف حكمه فأوتيه، وملكًا لا ينبغي لأحد من بعده فأوتيه، وأنه لا يأتي هذا المسجدَ أحدٌ لا يريد إلا الصلاة فيه إلا خرج من خطيئته كيوم ولدته أمه. قال النبي صلى الله عليه وسلم: أما اثنتان فقد أُعطيهما، وأرجو أن يكون قد أُعطي الثالثة.","source":"سنن النسائي، كتاب المساجد؛ وأخرجه ابن ماجه (1408) وأحمد","number":"693","grade":"صحيح (صححه الألباني، وصححه الحاكم ووافقه الذهبي)","url":"https://sunnah.com/nasai:693"},"bukhari-3431":{"id":"bukhari-3431","title":"ما من مولود إلا يمسه الشيطان إلا مريم وابنها","text":"معنى الحديث: ما من بني آدم مولود إلا يمسه الشيطان حين يولد فيستهل صارخًا من مس الشيطان، غير مريم وابنها. ثم يقول أبو هريرة: واقرؤوا إن شئتم: وإني أعيذها بك وذريتها من الشيطان الرجيم.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم","number":"3431","grade":"صحيح","url":"https://sunnah.com/bukhari:3431"},"bukhari-3411":{"id":"bukhari-3411","title":"كمل من الرجال كثير","text":"«كمل من الرجال كثير، ولم يكمل من النساء إلا آسية امرأة فرعون، ومريم بنت عمران، وإن فضل عائشة على النساء كفضل الثريد على سائر الطعام».","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم","number":"3411","grade":"صحيح","url":"https://sunnah.com/bukhari:3411"},"bukhari-3432":{"id":"bukhari-3432","title":"خير نسائها مريم","text":"«خير نسائها مريم ابنة عمران، وخير نسائها خديجة».","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم","number":"3432","grade":"صحيح","url":"https://sunnah.com/bukhari:3432"},"muslim-zakariya":{"id":"muslim-zakariya","title":"كان زكريا نجارًا","text":"معنى الحديث: أن النبي صلى الله عليه وسلم أخبر أن زكريا عليه السلام كان نجارًا.","source":"صحيح مسلم، كتاب الفضائل (من حديث أبي هريرة)","number":"","grade":"صحيح","url":""},"tirmidhi-2863":{"id":"tirmidhi-2863","title":"الكلمات الخمس التي أُمر بها يحيى","text":"معنى الحديث: إن الله أمر يحيى بن زكريا بخمس كلمات أن يعمل بها ويأمر بني إسرائيل أن يعملوا بها: أن يعبدوا الله ولا يشركوا به شيئًا، والصلاة، والصيام، والصدقة، وذكر الله؛ وضرب لكل واحدة مثلًا. فلما أبطأ بها قال له عيسى: إما أن تبلّغهن وإما أن أبلّغهن، فجمع يحيى الناس في بيت المقدس فبلّغهم.","source":"سنن الترمذي، كتاب الأمثال، وأخرجه أحمد وابن خزيمة والحاكم، من حديث الحارث الأشعري","number":"2863","grade":"صحيح (قال الترمذي: حسن صحيح غريب)","url":"https://sunnah.com/tirmidhi:2863"},"bukhari-3436":{"id":"bukhari-3436","title":"لم يتكلم في المهد إلا ثلاثة","text":"معنى الحديث: لم يتكلم في المهد إلا ثلاثة: عيسى، وصاحب جريج، وصبي كان يرضع من أمه فمر راكب ذو شارة فتمنت أمه أن يكون ابنها مثله فقال: اللهم لا تجعلني مثله…","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم، كتاب البر والصلة (2550)","number":"3436","grade":"صحيح","url":"https://sunnah.com/bukhari:3436"},"bukhari-3443":{"id":"bukhari-3443","title":"أنا أولى الناس بعيسى ابن مريم","text":"أنا أولى الناس بعيسى ابن مريم في الدنيا والآخرة، والأنبياء إخوة لعلّات، أمهاتهم شتى ودينهم واحد.","source":"صحيح البخاري، كتاب أحاديث الأنبياء؛ وصحيح مسلم (2365). وفي رواية للبخاري (3442): «ليس بيني وبينه نبي»","number":"3443","grade":"صحيح","url":"https://sunnah.com/bukhari:3443"},"bukhari-3448":{"id":"bukhari-3448","title":"نزول عيسى ابن مريم حكمًا عدلًا","text":"والذي نفسي بيده ليوشكن أن ينزل فيكم ابن مريم حكمًا عدلًا، فيكسر الصليب، ويقتل الخنزير، ويضع الجزية، ويفيض المال حتى لا يقبله أحد.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب نزول عيسى ابن مريم؛ وصحيح مسلم، كتاب الإيمان (155)","number":"3448","grade":"صحيح","url":"https://sunnah.com/bukhari:3448"},"muslim-2937":{"id":"muslim-2937","title":"حديث النواس بن سمعان في الدجال ونزول عيسى","text":"معنى الحديث: يبعث الله المسيح ابن مريم فينزل عند المنارة البيضاء شرقي دمشق، واضعًا كفيه على أجنحة ملكين، فيطلب الدجال حتى يدركه بباب لُدّ فيقتله، ثم يوحي الله إليه أن يحرز عباده إلى الطور لخروج يأجوج ومأجوج، فيدعو عليهم فيهلكهم الله.","source":"صحيح مسلم، كتاب الفتن وأشراط الساعة","number":"2937","grade":"صحيح","url":"https://sunnah.com/muslim:2937"},"bukhari-4625":{"id":"bukhari-4625","title":"فأقول كما قال العبد الصالح","text":"معنى الحديث: يُحشر الناس حفاة عراة غرلًا، ويؤخذ برجال من أمتي ذات الشمال فأقول: أصحابي، فيقال: إنك لا تدري ما أحدثوا بعدك، فأقول كما قال العبد الصالح: «وكنت عليهم شهيدًا ما دمت فيهم…».","source":"صحيح البخاري، كتاب التفسير، سورة المائدة (ورواه أيضًا في أحاديث الأنبياء)","number":"4625","grade":"صحيح","url":"https://sunnah.com/bukhari:4625"},"bukhari-4380":{"id":"bukhari-4380","title":"وفد نجران والمباهلة وأمين الأمة","text":"معنى الحديث: جاء العاقب والسيد صاحبا نجران إلى رسول الله صلى الله عليه وسلم يريدان أن يلاعناه (يباهلاه)، فقال أحدهما لصاحبه: لا تفعل، فوالله لئن كان نبيًا فلاعنّا لا نفلح نحن ولا عقبنا، فقالا: نعطيك ما سألتنا وابعث معنا رجلًا أمينًا، فبعث أبا عبيدة بن الجراح وقال: هذا أمين هذه الأمة.","source":"صحيح البخاري، كتاب المغازي، باب قصة أهل نجران؛ وصحيح مسلم (2420)","number":"4380","grade":"صحيح","url":"https://sunnah.com/bukhari:4380"},"ahmad-dawat-ibrahim":{"id":"ahmad-dawat-ibrahim","title":"أنا دعوة أبي إبراهيم وبشرى عيسى","text":"معنى الحديث: أنا دعوة أبي إبراهيم، وبشرى عيسى بي، ورؤيا أمي التي رأت أنه خرج منها نور أضاءت له قصور الشام.","source":"مسند الإمام أحمد من حديث العرباض بن سارية وأبي أمامة، ورواه ابن حبان والحاكم","number":"","grade":"صحيح لغيره عند جماعة من المحققين","url":""},"muslim-3005":{"id":"muslim-3005","title":"الملك والساحر والراهب والغلام","text":"معنى الحديث: كان ملك فيمن كان قبلكم وكان له ساحر، فلما كبر قال للملك: ابعث إلي غلامًا أعلّمه السحر، فكان الغلام يمر براهب فيسمع منه فأعجبه… حتى قال الغلام للملك: إنك لست بقاتلي حتى تفعل ما آمرك به: تجمع الناس في صعيد واحد وتصلبني على جذع وتقول: باسم الله رب الغلام، فلما قتله قال الناس: آمنا برب الغلام، فخدّ الأخاديد وأضرم فيها النيران.","source":"صحيح مسلم، كتاب الزهد والرقائق، باب قصة أصحاب الأخدود والساحر والراهب والغلام","number":"3005","grade":"صحيح","url":"https://sunnah.com/muslim:3005"},"bukhari-3826":{"id":"bukhari-3826","title":"زيد بن عمرو بن نفيل لا يأكل مما ذُبح على النصب","text":"معنى الحديث: أن النبي صلى الله عليه وسلم لقي زيد بن عمرو بن نفيل بأسفل بَلْدَح قبل أن ينزل عليه الوحي، فقُدّمت إليه سفرة فأبى أن يأكل منها، وقال: إني لا آكل مما تذبحون على أنصابكم، ولا آكل إلا ما ذُكر اسم الله عليه؛ وكان يعيب على قريش ذبائحهم ويقول: الشاة خلقها الله وأنزل لها من السماء الماء وأنبت لها من الأرض ثم تذبحونها على غير اسم الله!","source":"صحيح البخاري، كتاب مناقب الأنصار، باب حديث زيد بن عمرو بن نفيل","number":"3826","grade":"صحيح","url":"https://sunnah.com/bukhari:3826"},"bukhari-3827":{"id":"bukhari-3827","title":"رحلة زيد بن عمرو إلى الشام يسأل عن الدين","text":"معنى الحديث: خرج زيد إلى الشام يسأل عن الدين، فلقي عالمًا من اليهود فقال: لن تكون على ديننا حتى تأخذ بنصيبك من غضب الله، ولقي عالمًا من النصارى فقال: لن تكون على ديننا حتى تأخذ بنصيبك من لعنة الله، فقال زيد: ما أفرّ إلا من ذلك، فدلّاه على الحنيفية دين إبراهيم، فلما خرج رفع يديه وقال: اللهم إني أشهد أني على دين إبراهيم.","source":"صحيح البخاري، كتاب مناقب الأنصار، باب حديث زيد بن عمرو بن نفيل","number":"3827","grade":"صحيح","url":"https://sunnah.com/bukhari:3827"},"bukhari-3346":{"id":"bukhari-3346","title":"فُتح اليوم من ردم يأجوج ومأجوج مثل هذه","text":"معنى الحديث: دخل النبي صلى الله عليه وسلم على زينب بنت جحش فزعًا يقول: لا إله إلا الله، ويل للعرب من شر قد اقترب، فُتح اليوم من ردم يأجوج ومأجوج مثل هذه، وحلّق بإصبعيه، فقالت: أنهلك وفينا الصالحون؟ قال: نعم، إذا كثر الخبث.","source":"صحيح البخاري، كتاب أحاديث الأنبياء، باب قصة يأجوج ومأجوج؛ وصحيح مسلم (2880)","number":"3346","grade":"صحيح","url":"https://sunnah.com/bukhari:3346"},"bukhari-32":{"id":"bukhari-32","title":"الظلم في الآية هو الشرك كما قال لقمان","text":"معنى الحديث: لما نزلت «الذين آمنوا ولم يلبسوا إيمانهم بظلم» شق ذلك على الصحابة وقالوا: أيّنا لم يظلم نفسه؟ فبيّن النبي صلى الله عليه وسلم أن المراد الشرك، واستشهد بقول لقمان لابنه: إن الشرك لظلم عظيم.","source":"صحيح البخاري، كتاب الإيمان، باب ظلم دون ظلم (ورواه في أحاديث الأنبياء وفي التفسير)؛ وصحيح مسلم (124)","number":"32","grade":"صحيح","url":"https://sunnah.com/bukhari:32"},"bukhari-3841":{"id":"bukhari-3841","title":"أصدق كلمة قالها شاعر كلمة لبيد","text":"أصدق كلمة قالها الشاعر كلمة لبيد: ألا كل شيء ما خلا الله باطل، وكاد أمية بن أبي الصلت أن يسلم.","source":"صحيح البخاري، كتاب مناقب الأنصار، باب أيام الجاهلية؛ وصحيح مسلم (2256)","number":"3841","grade":"صحيح","url":"https://sunnah.com/bukhari:3841"},"hilf-fudul":{"id":"hilf-fudul","title":"لقد شهدت في دار عبد الله بن جدعان حلفًا","text":"معنى الحديث: لقد شهدت في دار عبد الله بن جدعان حلفًا ما أحب أن لي به حمر النعم، ولو أُدعى به في الإسلام لأجبت.","source":"سيرة ابن هشام (عن ابن إسحاق)؛ السنن الكبرى للبيهقي؛ وله شاهد في مسند أحمد بلفظ «شهدت حلف المطيّبين مع عمومتي وأنا غلام»","number":"","grade":"صححه بعض المحدثين بمجموع طرقه (كالألباني في فقه السيرة)، وفي أفراد أسانيده مقال","url":""},"ahmad-makarim":{"id":"ahmad-makarim","title":"إنما بعثت لأتمم صالح الأخلاق","text":"إنما بُعثت لأتمم صالح الأخلاق.","source":"مسند أحمد، والأدب المفرد للبخاري، من حديث أبي هريرة؛ ورواه مالك بلاغًا بلفظ «حسن الأخلاق»","number":"","grade":"صحيح","url":""},"bukhari-7":{"id":"bukhari-7","title":"حديث هرقل وأبي سفيان","text":"معنى الحديث: سأل هرقل أبا سفيان عن نسب النبي ﷺ وأتباعه وصدقه ووفائه وما يأمر به، ثم قال: إن كان ما تقول حقًا فسيملك موضع قدميّ هاتين، وقُرئ كتاب النبي ﷺ: أسلم تسلم يؤتك الله أجرك مرتين.","source":"صحيح البخاري، كتاب بدء الوحي","number":"7","grade":"صحيح","url":"https://sunnah.com/bukhari:7"},"muslim-2276":{"id":"muslim-2276","title":"اصطفاء كنانة وقريش وبني هاشم","text":"معنى الحديث: إن الله اصطفى كنانة من ولد إسماعيل، واصطفى قريشًا من كنانة، واصطفى من قريش بني هاشم، واصطفى النبي ﷺ من بني هاشم.","source":"صحيح مسلم، كتاب الفضائل، من حديث واثلة بن الأسقع","number":"2276","grade":"صحيح","url":"https://sunnah.com/muslim:2276"},"muslim-1162":{"id":"muslim-1162","title":"يوم الاثنين يوم المولد والمبعث","text":"معنى الحديث: سئل النبي ﷺ عن صوم يوم الاثنين فقال: ذاك يوم وُلدت فيه، ويوم بُعثت أو أُنزل عليّ فيه.","source":"صحيح مسلم، كتاب الصيام، من حديث أبي قتادة","number":"1162","grade":"صحيح","url":"https://sunnah.com/muslim:1162"},"muslim-976":{"id":"muslim-976","title":"زيارة النبي ﷺ قبر أمه","text":"معنى الحديث: زار النبي ﷺ قبر أمه فبكى وأبكى من حوله، وأخبر أنه استأذن ربه في زيارة قبرها فأذن له، وقال: فزوروا القبور فإنها تذكر الموت.","source":"صحيح مسلم، كتاب الجنائز، من حديث أبي هريرة","number":"976","grade":"صحيح","url":"https://sunnah.com/muslim:976"},"tirmidhi-3620":{"id":"tirmidhi-3620","title":"حديث الراهب في رحلة الشام","text":"معنى الحديث: خرج أبو طالب إلى الشام ومعه النبي ﷺ في أشياخ من قريش، فخرج إليهم الراهب فأخذ بيد النبي وقال: هذا سيد العالمين، وذكر سجود الشجر والحجر وخاتم النبوة، وأمر بردّه خوفًا عليه من الروم.","source":"سنن الترمذي، كتاب المناقب، من حديث أبي موسى الأشعري","number":"3620","grade":"حسنه الترمذي (حسن غريب)، واستنكر الذهبي وغيره بعض ألفاظه","url":"https://sunnah.com/tirmidhi:3620"},"bukhari-2262":{"id":"bukhari-2262","title":"رعي الغنم","text":"ما بعث الله نبيًا إلا رعى الغنم، فقال أصحابه: وأنت؟ فقال: نعم، كنت أرعاها على قراريط لأهل مكة.","source":"صحيح البخاري، كتاب الإجارة، من حديث أبي هريرة","number":"2262","grade":"صحيح","url":"https://sunnah.com/bukhari:2262"},"muslim-2435":{"id":"muslim-2435","title":"إني قد رزقت حبها","text":"معنى الحديث: قالت عائشة: ما غرت على امرأة ما غرت على خديجة لكثرة ذكر النبي ﷺ إياها، وكان يقول عنها: إني قد رُزقت حبها.","source":"صحيح مسلم، كتاب فضائل الصحابة، من حديث عائشة","number":"2435","grade":"صحيح","url":"https://sunnah.com/muslim:2435"},"bukhari-3820":{"id":"bukhari-3820","title":"بشارة خديجة ببيت في الجنة","text":"معنى الحديث: أتى جبريل النبي ﷺ فأخبره أن خديجة آتية بإناء فيه طعام، وأمره أن يقرأ عليها السلام من ربها ومنه، ويبشرها ببيت في الجنة من قصب لا صخب فيه ولا نصب.","source":"صحيح البخاري، كتاب مناقب الأنصار، من حديث أبي هريرة","number":"3820","grade":"صحيح","url":"https://sunnah.com/bukhari:3820"},"bukhari-3660":{"id":"bukhari-3660","title":"رأيت رسول الله وما معه إلا خمسة أعبد","text":"معنى الحديث: قال عمار بن ياسر: رأيت رسول الله ﷺ وما معه إلا خمسة أعبد وامرأتان وأبو بكر.","source":"صحيح البخاري، كتاب فضائل الصحابة","number":"3660","grade":"صحيح","url":"https://sunnah.com/bukhari:3660"},"bukhari-4770":{"id":"bukhari-4770","title":"النداء على الصفا","text":"معنى الحديث: لما نزلت آية إنذار العشيرة صعد النبي ﷺ على الصفا فنادى بطون قريش، فقال: أرأيتكم لو أخبرتكم أن خيلًا بالوادي تريد أن تغير عليكم أكنتم مصدقيّ؟ قالوا: ما جربنا عليك إلا صدقًا، قال: فإني نذير لكم بين يدي عذاب شديد، فقال أبو لهب: تبًّا لك، فنزلت سورة المسد.","source":"صحيح البخاري، كتاب التفسير، من حديث ابن عباس","number":"4770","grade":"صحيح","url":"https://sunnah.com/bukhari:4770"},"ibnmajah-150":{"id":"ibnmajah-150","title":"أول من أظهر إسلامه سبعة","text":"معنى الحديث: قال ابن مسعود: أول من أظهر إسلامه سبعة، منهم بلال، فأما بلال فهانت عليه نفسه في الله، فجعلوا يطوفون به في شعاب مكة وهو يقول: أحد أحد.","source":"سنن ابن ماجه، المقدمة","number":"150","grade":"حسن","url":"https://sunnah.com/ibnmajah:150"},"bukhari-240":{"id":"bukhari-240","title":"سلا الجزور على ظهر النبي ﷺ","text":"معنى الحديث: وضع عقبة بن أبي معيط سلا جزور على ظهر النبي ﷺ وهو ساجد عند الكعبة، فجاءت فاطمة فطرحته عنه، فدعا عليهم، قال ابن مسعود: فلقد رأيتهم صرعى في قليب بدر.","source":"صحيح البخاري، كتاب الوضوء، من حديث ابن مسعود","number":"240","grade":"صحيح","url":"https://sunnah.com/bukhari:240"},"muslim-2797":{"id":"muslim-2797","title":"لو دنا مني لاختطفته الملائكة","text":"معنى الحديث: حلف أبو جهل ليطأن رقبة النبي ﷺ إن رآه يصلي، فلما دنا نكص على عقبيه وقال: إن بيني وبينه لخندقًا من نار وهولًا وأجنحة، فقال النبي ﷺ: لو دنا مني لاختطفته الملائكة عضوًا عضوًا.","source":"صحيح مسلم، كتاب صفة القيامة والجنة والنار، من حديث أبي هريرة","number":"2797","grade":"صحيح","url":"https://sunnah.com/muslim:2797"},"bukhari-3612":{"id":"bukhari-3612","title":"ولكنكم تستعجلون","text":"معنى الحديث: شكا خباب وأصحابه إلى النبي ﷺ وهو متوسد بردة في ظل الكعبة، فذكر لهم صبر من قبلهم على المنشار وأمشاط الحديد، وأقسم ليتمّن الله هذا الأمر حتى يسير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله والذئب على غنمه، ولكنكم تستعجلون.","source":"صحيح البخاري، كتاب المناقب، من حديث خباب بن الأرت","number":"3612","grade":"صحيح","url":"https://sunnah.com/bukhari:3612"},"ahmad-1740":{"id":"ahmad-1740","title":"حديث الهجرة إلى الحبشة وكلمة جعفر","text":"معنى الحديث: تروي أم سلمة خبر المهاجرين إلى الحبشة، ووفد قريش إلى النجاشي، وخطبة جعفر بن أبي طالب في وصف الجاهلية والإسلام، وقراءته صدر سورة مريم، وبكاء النجاشي، وقوله إن هذا والذي جاء به عيسى ليخرج من مشكاة واحدة.","source":"مسند أحمد، من حديث أم سلمة","number":"1740","grade":"حسن الإسناد عند المحققين","url":""},"bukhari-1245":{"id":"bukhari-1245","title":"الصلاة على النجاشي","text":"معنى الحديث: نعى رسول الله ﷺ النجاشي في اليوم الذي مات فيه، وخرج بهم إلى المصلى فصف بهم وكبّر أربعًا.","source":"صحيح البخاري، كتاب الجنائز، من حديث أبي هريرة","number":"1245","grade":"صحيح","url":"https://sunnah.com/bukhari:1245"},"bukhari-3684":{"id":"bukhari-3684","title":"ما زلنا أعزة منذ أسلم عمر","text":"قال عبد الله بن مسعود: ما زلنا أعزة منذ أسلم عمر.","source":"صحيح البخاري، كتاب فضائل الصحابة","number":"3684","grade":"صحيح","url":"https://sunnah.com/bukhari:3684"},"bukhari-3884":{"id":"bukhari-3884","title":"وفاة أبي طالب","text":"معنى الحديث: دخل النبي ﷺ على أبي طالب عند موته فقال: أي عم، قل لا إله إلا الله كلمة أحاجّ لك بها عند الله، فقال أبو جهل وعبد الله بن أبي أمية: أترغب عن ملة عبد المطلب؟ فكان آخر ما قال: على ملة عبد المطلب، فقال النبي ﷺ: لأستغفرن لك ما لم أُنه عنك، فنزلت آية التوبة 113.","source":"صحيح البخاري، كتاب مناقب الأنصار، من حديث المسيب بن حزن","number":"3884","grade":"صحيح","url":"https://sunnah.com/bukhari:3884"},"bukhari-3231":{"id":"bukhari-3231","title":"يوم الطائف وملك الجبال","text":"معنى الحديث: سألت عائشة النبي ﷺ: هل أتى عليك يوم أشد من يوم أحد؟ فذكر يوم عرض نفسه على ابن عبد ياليل، وأن ملك الجبال عرض عليه أن يطبق عليهم الأخشبين، فقال: بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده لا يشرك به شيئًا.","source":"صحيح البخاري، كتاب بدء الخلق، من حديث عائشة","number":"3231","grade":"صحيح","url":"https://sunnah.com/bukhari:3231"},"bukhari-4862":{"id":"bukhari-4862","title":"السجود في سورة النجم","text":"معنى الحديث: سجد النبي ﷺ بالنجم، وسجد معه المسلمون والمشركون والجن والإنس.","source":"صحيح البخاري، كتاب التفسير، من حديث ابن عباس","number":"4862","grade":"صحيح","url":"https://sunnah.com/bukhari:4862"},"bukhari-3637":{"id":"bukhari-3637","title":"انشقاق القمر","text":"معنى الحديث: سأل أهل مكة رسول الله ﷺ أن يريهم آية، فأراهم انشقاق القمر.","source":"صحيح البخاري، كتاب المناقب، من حديث أنس بن مالك","number":"3637","grade":"صحيح","url":"https://sunnah.com/bukhari:3637"},"bukhari-18":{"id":"bukhari-18","title":"بيعة العقبة","text":"معنى الحديث: قال النبي ﷺ وحوله عصابة من أصحابه: بايعوني على ألا تشركوا بالله شيئًا، ولا تسرقوا، ولا تزنوا، ولا تقتلوا أولادكم، ولا تأتوا ببهتان تفترونه، ولا تعصوا في معروف، فمن وفى منكم فأجره على الله.","source":"صحيح البخاري، كتاب الإيمان، من حديث عبادة بن الصامت","number":"18","grade":"صحيح","url":"https://sunnah.com/bukhari:18"},"bukhari-3653":{"id":"bukhari-3653","title":"ما ظنك باثنين الله ثالثهما","text":"معنى الحديث: قال أبو بكر للنبي ﷺ وهما في الغار: لو أن أحدهم نظر تحت قدميه لأبصرنا، فقال: ما ظنك يا أبا بكر باثنين الله ثالثهما.","source":"صحيح البخاري، كتاب فضائل الصحابة، من حديث أبي بكر الصديق","number":"3653","grade":"صحيح","url":"https://sunnah.com/bukhari:3653"},"bukhari-3906":{"id":"bukhari-3906","title":"قصة سراقة بن مالك","text":"معنى الحديث: يروي سراقة أن قريشًا جعلت في النبي ﷺ وأبي بكر دية كل واحد منهما، فلحق بهما فساخت يدا فرسه في الأرض مرارًا، فطلب الأمان، وكتب له عامر بن فهيرة كتاب أمن.","source":"صحيح البخاري، كتاب مناقب الأنصار، باب هجرة النبي ﷺ","number":"3906","grade":"صحيح","url":"https://sunnah.com/bukhari:3906"},"bukhari-428":{"id":"bukhari-428","title":"بناء المسجد النبوي","text":"معنى الحديث: قال النبي ﷺ: يا بني النجار ثامنوني بحائطكم هذا، قالوا: لا والله لا نطلب ثمنه إلا إلى الله، فنُبشت قبور المشركين وسُوّيت الخرب وقُطع النخل، وكانوا يرتجزون والنبي معهم: اللهم لا خير إلا خير الآخرة، فاغفر للأنصار والمهاجرة.","source":"صحيح البخاري، كتاب الصلاة، من حديث أنس بن مالك","number":"428","grade":"صحيح","url":"https://sunnah.com/bukhari:428"},"bukhari-2049":{"id":"bukhari-2049","title":"المؤاخاة بين عبد الرحمن بن عوف وسعد بن الربيع","text":"معنى الحديث: آخى النبي ﷺ بين عبد الرحمن بن عوف وسعد بن الربيع، فعرض سعد أن يقاسمه ماله، فقال عبد الرحمن: بارك الله لك في أهلك ومالك، دلوني على السوق.","source":"صحيح البخاري، كتاب البيوع، من حديث أنس بن مالك","number":"2049","grade":"صحيح","url":"https://sunnah.com/bukhari:2049"},"bukhari-40":{"id":"bukhari-40","title":"تحويل القبلة","text":"معنى الحديث: صلى النبي ﷺ قبل بيت المقدس ستة عشر شهرًا أو سبعة عشر شهرًا، وكان يعجبه أن تكون قبلته قبل البيت، وأول صلاة صلاها إلى الكعبة صلاة العصر.","source":"صحيح البخاري، كتاب الإيمان، من حديث البراء بن عازب","number":"40","grade":"صحيح","url":"https://sunnah.com/bukhari:40"},"muslim-1763":{"id":"muslim-1763","title":"دعاء النبي ﷺ يوم بدر","text":"معنى الحديث: نظر النبي ﷺ يوم بدر إلى المشركين وهم ألف وأصحابه ثلاثمائة وتسعة عشر، فاستقبل القبلة ومدّ يديه يهتف: اللهم أنجز لي ما وعدتني، اللهم إن تهلك هذه العصابة من أهل الإسلام لا تعبد في الأرض، حتى سقط رداؤه، فأخذه أبو بكر وطمأنه، فنزلت آية الإمداد بالملائكة.","source":"صحيح مسلم، كتاب الجهاد والسير، من حديث عمر بن الخطاب","number":"1763","grade":"صحيح","url":"https://sunnah.com/muslim:1763"},"bukhari-3039":{"id":"bukhari-3039","title":"وصية النبي ﷺ للرماة يوم أحد","text":"معنى الحديث: جعل النبي ﷺ على الرماة يوم أحد عبد الله بن جبير، وقال: إن رأيتمونا تخطفنا الطير فلا تبرحوا مكانكم هذا حتى أرسل إليكم، فلما رأوا الهزيمة في المشركين قالوا: الغنيمة، فخالفوا، فكانت الدائرة على المسلمين.","source":"صحيح البخاري، كتاب الجهاد والسير، من حديث البراء بن عازب","number":"3039","grade":"صحيح","url":"https://sunnah.com/bukhari:3039"},"muslim-1791":{"id":"muslim-1791","title":"كيف يفلح قوم شجوا نبيهم","text":"معنى الحديث: كُسرت رباعية النبي ﷺ يوم أحد وشُجّ في رأسه، فجعل يسلت الدم عنه ويقول: كيف يفلح قوم شجوا نبيهم وكسروا رباعيته وهو يدعوهم إلى الله.","source":"صحيح مسلم، كتاب الجهاد والسير، من حديث أنس بن مالك","number":"1791","grade":"صحيح","url":"https://sunnah.com/muslim:1791"},"bukhari-4101":{"id":"bukhari-4101","title":"الصخرة يوم الخندق","text":"معنى الحديث: عرضت للصحابة يوم الخندق كدية شديدة، فنزل النبي ﷺ وبطنه معصوب بحجر من الجوع، فضربها بالمعول فعادت كثيبًا أهيل، ثم كان تكثير طعام جابر.","source":"صحيح البخاري، كتاب المغازي، من حديث جابر بن عبد الله","number":"4101","grade":"صحيح","url":"https://sunnah.com/bukhari:4101"},"bukhari-4119":{"id":"bukhari-4119","title":"لا يصلين أحد العصر إلا في بني قريظة","text":"معنى الحديث: قال النبي ﷺ يوم الأحزاب: لا يصلين أحد العصر إلا في بني قريظة، فأدرك بعضهم العصر في الطريق، فصلى بعضهم وأخّر بعضهم، فلم يعنّف واحدًا منهم.","source":"صحيح البخاري، كتاب المغازي، من حديث ابن عمر","number":"4119","grade":"صحيح","url":"https://sunnah.com/bukhari:4119"},"bukhari-4121":{"id":"bukhari-4121","title":"حكم سعد بن معاذ في بني قريظة","text":"معنى الحديث: نزل بنو قريظة على حكم سعد بن معاذ، فحكم بأن تُقتل المقاتلة وتُسبى الذرية، فقال النبي ﷺ: لقد حكمت فيهم بحكم الله، وفي رواية: بحكم الملك.","source":"صحيح البخاري، كتاب المغازي، من حديث أبي سعيد الخدري (وأخرجه مسلم)","number":"4121","grade":"صحيح","url":"https://sunnah.com/bukhari:4121"},"bukhari-2731":{"id":"bukhari-2731","title":"حديث صلح الحديبية","text":"معنى الحديث: يروي المسور بن مخرمة ومروان خبر الحديبية: بروك القصواء، وقول النبي ﷺ: لا يسألونني خطة يعظمون فيها حرمات الله إلا أعطيتهم إياها، ومفاوضة سهيل بن عمرو، وكتابة الصلح، وقصة أبي جندل، ومشورة أم سلمة.","source":"صحيح البخاري، كتاب الشروط","number":"2731","grade":"صحيح","url":"https://sunnah.com/bukhari:2731"},"bukhari-64":{"id":"bukhari-64","title":"كتاب النبي ﷺ إلى كسرى","text":"معنى الحديث: بعث النبي ﷺ بكتابه إلى كسرى مع عبد الله بن حذافة، فلما قرأه كسرى مزّقه، فدعا عليهم النبي ﷺ أن يمزقوا كل ممزق.","source":"صحيح البخاري، كتاب العلم، من حديث ابن عباس","number":"64","grade":"صحيح","url":"https://sunnah.com/bukhari:64"},"bukhari-3701":{"id":"bukhari-3701","title":"لأعطين الراية غدًا","text":"معنى الحديث: قال النبي ﷺ يوم خيبر: لأعطين الراية غدًا رجلًا يفتح الله على يديه، يحب الله ورسوله ويحبه الله ورسوله، فأعطاها عليًا بعد أن دعا له فبرأت عيناه، وقال: فوالله لأن يهدي الله بك رجلًا واحدًا خير لك من أن يكون لك حمر النعم.","source":"صحيح البخاري، كتاب فضائل الصحابة، من حديث سهل بن سعد","number":"3701","grade":"صحيح","url":"https://sunnah.com/bukhari:3701"},"bukhari-4262":{"id":"bukhari-4262","title":"نعي أمراء مؤتة","text":"معنى الحديث: نعى النبي ﷺ زيدًا وجعفرًا وابن رواحة قبل أن يأتي خبرهم، وعيناه تذرفان، وقال: حتى أخذ الراية سيف من سيوف الله حتى فتح الله عليهم.","source":"صحيح البخاري، كتاب المغازي، من حديث أنس بن مالك","number":"4262","grade":"صحيح","url":"https://sunnah.com/bukhari:4262"},"muslim-1780":{"id":"muslim-1780","title":"أمان يوم الفتح","text":"معنى الحديث: قال النبي ﷺ يوم فتح مكة: من دخل دار أبي سفيان فهو آمن، ومن ألقى السلاح فهو آمن، ومن أغلق بابه فهو آمن.","source":"صحيح مسلم، كتاب الجهاد والسير، من حديث أبي هريرة","number":"1780","grade":"صحيح","url":"https://sunnah.com/muslim:1780"},"bukhari-4287":{"id":"bukhari-4287","title":"جاء الحق وزهق الباطل","text":"معنى الحديث: دخل النبي ﷺ مكة يوم الفتح وحول البيت ستون وثلاثمائة نُصُب، فجعل يطعنها بعود في يده ويقول: جاء الحق وزهق الباطل، جاء الحق وما يبدئ الباطل وما يعيد.","source":"صحيح البخاري، كتاب المغازي، من حديث عبد الله بن مسعود","number":"4287","grade":"صحيح","url":"https://sunnah.com/bukhari:4287"},"bukhari-2864":{"id":"bukhari-2864","title":"أنا النبي لا كذب","text":"معنى الحديث: سئل البراء: أفررتم يوم حنين؟ فقال: لكن رسول الله ﷺ لم يفر، كان على بغلته البيضاء وهو يقول: أنا النبي لا كذب، أنا ابن عبد المطلب.","source":"صحيح البخاري، كتاب الجهاد والسير، من حديث البراء بن عازب","number":"2864","grade":"صحيح","url":"https://sunnah.com/bukhari:2864"},"bukhari-4330":{"id":"bukhari-4330","title":"خطبة النبي ﷺ في الأنصار بعد حنين","text":"معنى الحديث: جمع النبي ﷺ الأنصار بعد قسمة غنائم حنين فذكّرهم بهداية الله لهم به وتأليفه بينهم وإغنائهم، ثم قال: أترضون أن يذهب الناس بالشاة والبعير وتذهبون بالنبي إلى رحالكم؟ لولا الهجرة لكنت امرأً من الأنصار، الأنصار شعار والناس دثار.","source":"صحيح البخاري، كتاب المغازي، من حديث عبد الله بن زيد بن عاصم","number":"4330","grade":"صحيح","url":"https://sunnah.com/bukhari:4330"},"bukhari-4418":{"id":"bukhari-4418","title":"حديث كعب بن مالك","text":"معنى الحديث: يروي كعب بن مالك قصة تخلفه عن غزوة تبوك بلا عذر، وصدقه مع النبي ﷺ، ومقاطعة المسلمين له ولصاحبيه خمسين ليلة، ثم نزول توبة الله عليهم، وقوله: إن الله إنما نجاني بالصدق.","source":"صحيح البخاري، كتاب المغازي","number":"4418","grade":"صحيح","url":"https://sunnah.com/bukhari:4418"},"bukhari-63":{"id":"bukhari-63","title":"حديث ضمام بن ثعلبة","text":"معنى الحديث: دخل رجل على جمل فأناخه في المسجد وقال: أيكم محمد؟ ثم سأله مشددًا: آلله أرسلك إلى الناس كلهم؟ وعن الصلاة والصيام والزكاة، فلما أجابه قال: آمنت بما جئت به، وأنا ضمام بن ثعلبة أخو بني سعد بن بكر.","source":"صحيح البخاري، كتاب العلم، من حديث أنس بن مالك","number":"63","grade":"صحيح","url":"https://sunnah.com/bukhari:63"},"muslim-1218":{"id":"muslim-1218","title":"حديث جابر في حجة الوداع","text":"معنى الحديث: يصف جابر حجة النبي ﷺ، ومنها خطبته بعرفة: إن دماءكم وأموالكم حرام عليكم كحرمة يومكم هذا في شهركم هذا في بلدكم هذا، ووضع دماء الجاهلية وربا الجاهلية، والوصية بالنساء، وقوله: وقد تركت فيكم ما لن تضلوا بعده إن اعتصمتم به كتاب الله، ثم استشهاده الناس: اللهم اشهد.","source":"صحيح مسلم، كتاب الحج","number":"1218","grade":"صحيح","url":"https://sunnah.com/muslim:1218"},"bukhari-45":{"id":"bukhari-45","title":"نزول آية إكمال الدين","text":"معنى الحديث: قال رجل من اليهود لعمر: آية في كتابكم لو علينا نزلت لاتخذنا ذلك اليوم عيدًا، فقال عمر: قد عرفنا ذلك اليوم والمكان الذي نزلت فيه، نزلت على النبي ﷺ وهو قائم بعرفة يوم جمعة.","source":"صحيح البخاري، كتاب الإيمان، من حديث عمر بن الخطاب","number":"45","grade":"صحيح","url":"https://sunnah.com/bukhari:45"},"bukhari-4463":{"id":"bukhari-4463","title":"اللهم الرفيق الأعلى","text":"معنى الحديث: كان النبي ﷺ يقول وهو صحيح: إنه لم يُقبض نبي قط حتى يرى مقعده من الجنة ثم يُخيّر، فلما نزل به ورأسه على فخذ عائشة غُشي عليه، ثم أفاق فأشخص بصره إلى السقف وقال: اللهم الرفيق الأعلى.","source":"صحيح البخاري، كتاب المغازي، باب آخر ما تكلم به النبي ﷺ، من حديث عائشة","number":"4463","grade":"صحيح","url":"https://sunnah.com/bukhari:4463"},"bukhari-3536":{"id":"bukhari-3536","title":"سن النبي ﷺ عند وفاته","text":"معنى الحديث: عن عائشة أن النبي ﷺ توفي وهو ابن ثلاث وستين.","source":"صحيح البخاري، كتاب المناقب، من حديث عائشة","number":"3536","grade":"صحيح","url":"https://sunnah.com/bukhari:3536"},"bukhari-3668":{"id":"bukhari-3668","title":"كلمة أبي بكر عند وفاة النبي ﷺ","text":"ألا من كان يعبد محمدًا فإن محمدًا قد مات، ومن كان يعبد الله فإن الله حي لا يموت.","source":"صحيح البخاري، كتاب فضائل الصحابة، من حديث عائشة","number":"3668","grade":"صحيح","url":"https://sunnah.com/bukhari:3668"},"bukhari-3583":{"id":"bukhari-3583","title":"حنين الجذع","text":"معنى الحديث: كان النبي ﷺ يخطب إلى جذع، فلما اتخذ المنبر تحول إليه، فحنّ الجذع، فأتاه فمسح يده عليه.","source":"صحيح البخاري، كتاب المناقب، باب علامات النبوة في الإسلام، من حديث ابن عمر","number":"3583","grade":"صحيح","url":"https://sunnah.com/bukhari:3583"},"bukhari-220":{"id":"bukhari-220","title":"الأعرابي الذي بال في المسجد","text":"معنى الحديث: قام أعرابي فبال في المسجد، فتناوله الناس، فقال لهم النبي ﷺ: دعوه، وهريقوا على بوله سجلًا من ماء أو ذنوبًا من ماء، فإنما بعثتم ميسّرين ولم تبعثوا معسّرين.","source":"صحيح البخاري، كتاب الوضوء، من حديث أبي هريرة","number":"220","grade":"صحيح","url":"https://sunnah.com/bukhari:220"},"abudawud-2549":{"id":"abudawud-2549","title":"الجمل الذي شكا صاحبه","text":"معنى الحديث: دخل النبي ﷺ حائطًا لرجل من الأنصار فإذا جمل، فلما رآه حنّ وذرفت عيناه، فمسح ذفراه فسكت، ثم قال لصاحبه: أفلا تتقي الله في هذه البهيمة التي ملّكك الله إياها، فإنه شكا إليّ أنك تجيعه وتدئبه.","source":"سنن أبي داود، كتاب الجهاد، من حديث عبد الله بن جعفر","number":"2549","grade":"صحيح (صححه الألباني، وقال الأرناؤوط: إسناده صحيح)","url":"https://sunnah.com/abudawud:2549"},"bukhari-3576":{"id":"bukhari-3576","title":"نبع الماء من بين الأصابع","text":"معنى الحديث: عطش الناس يوم الحديبية، فوضع النبي ﷺ يده في الركوة فجعل الماء يثور بين أصابعه كأمثال العيون، فشربوا وتوضؤوا، وكانوا خمس عشرة مائة.","source":"صحيح البخاري، كتاب المناقب، باب علامات النبوة، من حديث جابر بن عبد الله","number":"3576","grade":"صحيح","url":"https://sunnah.com/bukhari:3576"},"bukhari-3535":{"id":"bukhari-3535","title":"مثلي ومثل الأنبياء","text":"معنى الحديث: مثل النبي ﷺ ومثل الأنبياء من قبله كرجل بنى بيتًا فأحسنه وأجمله إلا موضع لبنة من زاوية، فجعل الناس يطوفون به ويعجبون ويقولون: هلا وُضعت هذه اللبنة؟ قال: فأنا اللبنة، وأنا خاتم النبيين.","source":"صحيح البخاري، كتاب المناقب، من حديث أبي هريرة","number":"3535","grade":"صحيح","url":"https://sunnah.com/bukhari:3535"},"bukhari-3667":{"id":"bukhari-3667","title":"خطبة أبي بكر يوم الوفاة","text":"معنى الحديث: أن أبا بكر خرج والناس في اضطراب بعد وفاة النبي صلى الله عليه وسلم، فقال: من كان يعبد محمدًا فإن محمدًا قد مات، ومن كان يعبد الله فإن الله حي لا يموت، وتلا آية آل عمران: 144.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"","grade":"صحيح","url":""},"bukhari-6830":{"id":"bukhari-6830","title":"حديث السقيفة","text":"معنى الحديث: خطبة عمر بن الخطاب في المدينة التي حكى فيها ما جرى في سقيفة بني ساعدة، وكيف بايع هو والناس أبا بكر حسمًا للفرقة.","source":"صحيح البخاري، كتاب الحدود","number":"6830","grade":"صحيح","url":"https://sunnah.com/bukhari:6830"},"bukhari-1399":{"id":"bukhari-1399","title":"قتال مانعي الزكاة","text":"من قول أبي بكر: «والله لأقاتلن من فرق بين الصلاة والزكاة»","source":"صحيح البخاري، كتاب الزكاة","number":"1399","grade":"صحيح","url":"https://sunnah.com/bukhari:1399"},"bukhari-4986":{"id":"bukhari-4986","title":"جمع القرآن في عهد أبي بكر","text":"معنى الحديث: يروي زيد بن ثابت أن عمر أشار على أبي بكر بجمع القرآن بعد استحرار القتل بالقراء يوم اليمامة، فتردد ثم شرح الله صدره، فكلف زيدًا فتتبع القرآن من العسب واللخاف وصدور الرجال.","source":"صحيح البخاري، كتاب فضائل القرآن","number":"4986","grade":"صحيح","url":"https://sunnah.com/bukhari:4986"},"bukhari-4987":{"id":"bukhari-4987","title":"نسخ المصاحف في عهد عثمان","text":"معنى الحديث: قدم حذيفة بن اليمان على عثمان فزعًا من اختلاف الناس في القراءة، فأرسل عثمان إلى حفصة فأخذ الصحف ونسخها في المصاحف وأرسل إلى كل أفق بمصحف.","source":"صحيح البخاري، كتاب فضائل القرآن","number":"4987","grade":"صحيح","url":"https://sunnah.com/bukhari:4987"},"bukhari-3683":{"id":"bukhari-3683","title":"ما لقيك الشيطان سالكًا فجًّا","text":"معنى الحديث: قال النبي صلى الله عليه وسلم لعمر: والذي نفسي بيده ما لقيك الشيطان سالكًا فجًّا قط إلا سلك فجًّا غير فجك.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"3683","grade":"صحيح","url":"https://sunnah.com/bukhari:3683"},"bukhari-5729":{"id":"bukhari-5729","title":"الطاعون وخروج عمر إلى الشام","text":"معنى الحديث: خرج عمر إلى الشام فلما بلغ سرغ أُخبر بوقوع الوباء، فاستشار المهاجرين والأنصار ثم قرر الرجوع، فقال له أبو عبيدة: أفرارًا من قدر الله؟ فقال: نعم، نفر من قدر الله إلى قدر الله، ثم جاء عبد الرحمن بن عوف بالحديث: إذا سمعتم به بأرض فلا تقدموا عليه، وإذا وقع بأرض وأنتم بها فلا تخرجوا فرارًا منه.","source":"صحيح البخاري، كتاب الطب","number":"5729","grade":"صحيح","url":"https://sunnah.com/bukhari:5729"},"bukhari-3744":{"id":"bukhari-3744","title":"أمين هذه الأمة","text":"معنى الحديث: إن لكل أمة أمينًا، وإن أمين هذه الأمة أبو عبيدة بن الجراح.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"3744","grade":"صحيح","url":"https://sunnah.com/bukhari:3744"},"tirmidhi-3701":{"id":"tirmidhi-3701","title":"ما ضر عثمان ما عمل بعد اليوم","text":"معنى الحديث: جاء عثمان بألف دينار حين جهز جيش العسرة فنثرها في حجر النبي صلى الله عليه وسلم، فجعل يقلبها ويقول: «ما ضر عثمان ما عمل بعد اليوم» مرتين.","source":"سنن الترمذي، أبواب المناقب، من حديث عبد الرحمن بن سمرة","number":"3701","grade":"حسن (قال الترمذي: حسن غريب، وحسنه الألباني)","url":"https://sunnah.com/tirmidhi:3701"},"bukhari-3674":{"id":"bukhari-3674","title":"بشره بالجنة على بلوى تصيبه","text":"معنى الحديث: حديث أبي موسى الأشعري في بئر أريس، وفيه أن النبي صلى الله عليه وسلم أمر أن يُبشَّر أبو بكر ثم عمر بالجنة، ثم قال في عثمان: ائذن له وبشره بالجنة على بلوى تصيبه.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"","grade":"صحيح","url":""},"bukhari-4210":{"id":"bukhari-4210","title":"لأعطين الراية غدًا","text":"«لأعطين هذه الراية غدًا رجلًا يفتح الله على يديه، يحب الله ورسوله، ويحبه الله ورسوله»","source":"صحيح البخاري، كتاب المغازي، غزوة خيبر؛ ومسلم (2406) بنحوه","number":"4210","grade":"صحيح","url":"https://sunnah.com/bukhari:4210"},"bukhari-4481":{"id":"bukhari-4481","title":"أقضانا علي","text":"قال عمر: «أقرؤنا أُبي، وأقضانا علي»","source":"صحيح البخاري، كتاب التفسير","number":"4481","grade":"صحيح","url":"https://sunnah.com/bukhari:4481"},"bukhari-4750":{"id":"bukhari-4750","title":"حديث الإفك","text":"معنى الحديث: رواية عائشة الطويلة لحادثة الإفك منذ تخلفها عن الجيش في غزوة بني المصطلق إلى نزول براءتها من فوق سبع سماوات.","source":"صحيح البخاري، كتاب التفسير، سورة النور","number":"4750","grade":"صحيح","url":"https://sunnah.com/bukhari:4750"},"bukhari-3770":{"id":"bukhari-3770","title":"فضل عائشة كفضل الثريد","text":"«فضل عائشة على النساء كفضل الثريد على سائر الطعام»","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"3770","grade":"صحيح","url":"https://sunnah.com/bukhari:3770"},"tirmidhi-3883":{"id":"tirmidhi-3883","title":"علم عائشة","text":"معنى الحديث: قال أبو موسى الأشعري: ما أشكل علينا أصحاب رسول الله صلى الله عليه وسلم حديث قط فسألنا عائشة إلا وجدنا عندها منه علمًا.","source":"سنن الترمذي، أبواب المناقب","number":"3883","grade":"صحيح (قال الترمذي: حسن صحيح غريب)","url":"https://sunnah.com/tirmidhi:3883"},"bukhari-3818":{"id":"bukhari-3818","title":"الغيرة من خديجة","text":"معنى الحديث: قالت عائشة: ما غرت على أحد من نساء النبي صلى الله عليه وسلم ما غرت على خديجة، وما رأيتها، ولكن كان يكثر ذكرها، وربما ذبح الشاة ثم يقطعها أعضاء ثم يبعثها في صدائق خديجة.","source":"صحيح البخاري، كتاب مناقب الأنصار","number":"3818","grade":"صحيح","url":"https://sunnah.com/bukhari:3818"},"bukhari-3767":{"id":"bukhari-3767","title":"فاطمة بضعة مني","text":"«فاطمة بضعة مني، فمن أغضبها أغضبني»","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"3767","grade":"صحيح","url":"https://sunnah.com/bukhari:3767"},"bukhari-3623":{"id":"bukhari-3623","title":"سرّ النبي إلى فاطمة","text":"معنى الحديث: أسرّ النبي صلى الله عليه وسلم في مرضه إلى فاطمة فبكت، ثم أسرّ إليها فضحكت، فلما تُوفي أخبرت أنه أخبرها أولًا بقرب أجله، ثم أخبرها أنها أول أهله لحوقًا به وأنها سيدة نساء أهل الجنة أو نساء المؤمنين.","source":"صحيح البخاري، كتاب المناقب؛ ومسلم في فضائل الصحابة","number":"3623","grade":"صحيح","url":"https://sunnah.com/bukhari:3623"},"bukhari-1149":{"id":"bukhari-1149","title":"دف نعلي بلال","text":"معنى الحديث: سأل النبي صلى الله عليه وسلم بلالًا عن أرجى عمل عمله في الإسلام، فإنه سمع دف نعليه بين يديه في الجنة، فقال: ما عملت عملًا أرجى عندي من أني لم أتطهر طهورًا في ساعة من ليل أو نهار إلا صليت بذلك الطهور ما كتب لي أن أصلي.","source":"صحيح البخاري، كتاب التهجد","number":"1149","grade":"صحيح","url":"https://sunnah.com/bukhari:1149"},"bukhari-1276":{"id":"bukhari-1276","title":"كفن مصعب بن عمير","text":"معنى الحديث: قال خباب بن الأرت: هاجرنا مع النبي صلى الله عليه وسلم نلتمس وجه الله فوقع أجرنا على الله، فمنا من مات لم يأكل من أجره شيئًا، منهم مصعب بن عمير، قُتل يوم أحد فلم نجد ما نكفنه إلا بُردة إذا غطينا بها رأسه خرجت رجلاه، وإذا غطينا رجليه خرج رأسه، فأمرنا النبي أن نغطي رأسه ونجعل على رجليه من الإذخر.","source":"صحيح البخاري، كتاب الجنائز","number":"1276","grade":"صحيح","url":"https://sunnah.com/bukhari:1276"},"bukhari-3757":{"id":"bukhari-3757","title":"سيف من سيوف الله","text":"معنى الحديث: نعى النبي صلى الله عليه وسلم زيدًا وجعفرًا وابن رواحة قبل أن يأتي خبرهم، وعيناه تذرفان، ثم قال: حتى أخذ الراية سيف من سيوف الله حتى فتح الله عليهم.","source":"صحيح البخاري، كتاب فضائل أصحاب النبي صلى الله عليه وسلم","number":"3757","grade":"صحيح","url":"https://sunnah.com/bukhari:3757"},"muslim-2916":{"id":"muslim-2916","title":"تقتل عمارًا الفئة الباغية","text":"«تقتل عمارًا الفئة الباغية»","source":"صحيح مسلم، كتاب الفتن وأشراط الساعة؛ وأصله في البخاري","number":"2916","grade":"صحيح","url":"https://sunnah.com/muslim:2916"},"bukhari-2704":{"id":"bukhari-2704","title":"إن ابني هذا سيد","text":"«إن ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين»","source":"صحيح البخاري، كتاب الصلح","number":"2704","grade":"صحيح","url":"https://sunnah.com/bukhari:2704"},"muslim-2542":{"id":"muslim-2542","title":"خير التابعين أويس","text":"«إن خير التابعين رجل يقال له أويس، وله والدة، وكان به بياض، فمروه فليستغفر لكم»","source":"صحيح مسلم، كتاب فضائل الصحابة","number":"2542","grade":"صحيح","url":"https://sunnah.com/muslim:2542"},"muslim-muqaddima-ibnsirin":{"id":"muslim-muqaddima-ibnsirin","title":"إن هذا العلم دين","text":"قال محمد بن سيرين: «إن هذا العلم دين، فانظروا عمن تأخذون دينكم»","source":"مقدمة صحيح مسلم","number":"","grade":"صحيح الإسناد إلى ابن سيرين","url":""},"bukhari-tadwin-umar":{"id":"bukhari-tadwin-umar","title":"كتاب عمر بن عبد العزيز في تدوين الحديث","text":"معنى الأثر: كتب عمر بن عبد العزيز إلى أبي بكر بن حزم: انظر ما كان من حديث رسول الله صلى الله عليه وسلم فاكتبه، فإني خفت دروس العلم وذهاب العلماء.","source":"صحيح البخاري تعليقًا، كتاب العلم، باب كيف يُقبض العلم","number":"","grade":"أثر علقه البخاري بصيغة الجزم","url":""},"bukhari-71":{"id":"bukhari-71","title":"من يرد الله به خيرًا يفقهه في الدين","text":"«من يرد الله به خيرًا يفقهه في الدين»","source":"صحيح البخاري، كتاب العلم؛ وصحيح مسلم، كتاب الزكاة","number":"71","grade":"صحيح","url":"https://sunnah.com/bukhari:71"},"bukhari-1":{"id":"bukhari-1","title":"إنما الأعمال بالنيات","text":"«إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى»","source":"صحيح البخاري، كتاب بدء الوحي، أول حديث في الكتاب","number":"1","grade":"صحيح","url":"https://sunnah.com/bukhari:1"},"tirmidhi-2656":{"id":"tirmidhi-2656","title":"نضّر الله امرأً","text":"معنى الحديث: دعا النبي صلى الله عليه وسلم بالنضارة لمن سمع منه حديثًا فحفظه حتى يبلغه غيره، فرب حامل فقه إلى من هو أفقه منه.","source":"سنن الترمذي، أبواب العلم؛ وسنن أبي داود","number":"2656","grade":"صحيح","url":"https://sunnah.com/tirmidhi:2656"},"bukhari-6502":{"id":"bukhari-6502","title":"من عادى لي وليًّا","text":"معنى الحديث القدسي: من عادى لله وليًّا فقد آذنه الله بالحرب، وما تقرب عبد إلى الله بشيء أحب إليه مما افترضه عليه، ولا يزال يتقرب بالنوافل حتى يحبه الله، فإذا أحبه سدده في سمعه وبصره ويده ورجله، وإن سأله أعطاه، وإن استعاذه أعاذه.","source":"صحيح البخاري، كتاب الرقاق","number":"6502","grade":"صحيح","url":"https://sunnah.com/bukhari:6502"},"muslim-2622":{"id":"muslim-2622","title":"رب أشعث مدفوع بالأبواب","text":"«رب أشعث مدفوع بالأبواب لو أقسم على الله لأبره»","source":"صحيح مسلم، كتاب البر والصلة والآداب","number":"2622","grade":"صحيح","url":"https://sunnah.com/muslim:2622"},"ahmad-constantinople":{"id":"ahmad-constantinople","title":"لتفتحن القسطنطينية","text":"معنى الحديث المروي: لتفتحن القسطنطينية، فلنعم الأمير أميرها، ولنعم الجيش ذلك الجيش.","source":"مسند أحمد؛ والمستدرك للحاكم؛ من حديث بشر الخثعمي أو الغنوي","number":"","grade":"ضعيف (ضعفه الألباني في السلسلة الضعيفة لجهالة عبد الله بن بشر الراوي عن أبيه، وصححه الحاكم)","url":""},"ahmad-madinat-heraql":{"id":"ahmad-madinat-heraql","title":"مدينة هرقل تفتح أولًا","text":"معنى الحديث: سُئل النبي صلى الله عليه وسلم: أي المدينتين تُفتح أولًا: القسطنطينية أو رومية؟ فقال: مدينة هرقل تفتح أولًا، يعني القسطنطينية.","source":"مسند أحمد وسنن الدارمي من حديث عبد الله بن عمرو","number":"","grade":"صحيح (صححه الحاكم والألباني في السلسلة الصحيحة)","url":""},"muslim-2564":{"id":"muslim-2564","title":"إن الله لا ينظر إلى صوركم","text":"«إن الله لا ينظر إلى صوركم وأموالكم، ولكن ينظر إلى قلوبكم وأعمالكم»","source":"صحيح مسلم، كتاب البر والصلة والآداب","number":"2564","grade":"صحيح","url":"https://sunnah.com/muslim:2564"},"muslim-223":{"id":"muslim-223","title":"الطهور شطر الإيمان","text":"«الطهور شطر الإيمان»","source":"صحيح مسلم، كتاب الطهارة","number":"223","grade":"صحيح","url":"https://sunnah.com/muslim:223"}};
